insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f007','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','Taphonomy is the study of everything that happens to an organism between its death and its discovery as a fossil - decay, transport, burial and chemical change.','From Greek ''taphos'' = burial. It tells us how much of the original community is missing from a fossil bed.',null,true,2,2,635) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f008','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','Living fossils are present-day organisms almost unchanged from very old relatives: Lingula (brachiopod), Nautilus, Limulus (horseshoe crab), Latimeria (coelacanth fish) and Ginkgo (tree).','They evolved very slowly, so they have long time ranges. That makes them poor index fossils.',null,true,2,2,636) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f009','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','Principle of faunal succession (William Smith): fossil groups follow one another through the rock pile in a definite, non-repeating order, so beds with the same fossils are of the same age.','Smith was an English canal surveyor (about 1800). This principle is the base of biostratigraphy and of the geological time-scale.',null,true,3,1,637) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f010','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','The ''Big Five'' mass extinctions occurred at the end-Ordovician, Late Devonian, end-Permian, end-Triassic and end-Cretaceous.','Memory order: O-D-P-T-K. They explain several of the big breaks in the geological time-scale.',null,true,3,1,638) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f011','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','The end-Permian extinction (about 252 million years ago) was the largest; it finished off trilobites, rugose and tabulate corals, fusulinid foraminifera and blastoids.','It is called ''the Great Dying'' and marks the Palaeozoic-Mesozoic boundary. It is linked to the huge Siberian Traps eruptions.',null,true,3,1,639) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f012','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','The end-Cretaceous extinction (66 million years ago) removed ammonites, belemnites, rudist bivalves and non-avian dinosaurs; it is tied to the Chicxulub impact and an iridium-rich boundary clay.','It marks the Mesozoic-Cenozoic boundary. Deccan Trap volcanism in India was erupting at about the same time.','IIT-JAM Geology 2022',true,3,1,640) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f013','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','In the Cambrian explosion (from about 540 million years ago) most animal phyla with hard parts appear abruptly; the Middle Cambrian Burgess Shale of Canada preserves its soft-bodied animals.','Hard shells fossilise easily, so the record suddenly becomes rich. This is why the Phanerozoic (''visible life'') starts with the Cambrian.',null,true,3,1,641) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f014','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','The Devonian is the ''Age of Fishes''; amphibians first appeared in the Late Devonian and reptiles in the Carboniferous. The Mesozoic is the ''Age of Reptiles'', the Cenozoic the ''Age of Mammals''.','Order of backboned animals: fish, amphibians, reptiles, then mammals and birds. Each step moved life further away from water.',null,true,3,1,642) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f015','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','Dinosaurs and mammals both first appeared in the Triassic; the earliest known bird, Archaeopteryx, comes from the Late Jurassic Solnhofen Limestone of Germany.','Archaeopteryx had feathers like a bird but teeth and a long bony tail like a reptile - a classic connecting link.',null,true,3,1,643) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f016','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','Vascular land plants first appeared in the Silurian, coal-forming forests peaked in the Carboniferous, and flowering plants (angiosperms) appeared in the Early Cretaceous.','Plants colonised the land before backboned animals did. Angiosperms came late but dominate the Cenozoic.',null,true,3,1,644) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f017','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','In brachiopods each valve is bilaterally symmetrical but the two valves are unequal; in a typical bivalve the two valves are mirror images but each valve is lopsided.','Hook: a brachiopod valve looks the same on its left and right, like a face. In a clam the symmetry plane runs between the valves instead.',null,true,3,1,645) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f018','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','A brachiopod has a larger pedicle (ventral) valve with an opening for its fleshy stalk - a round pedicle foramen or a triangular notch, the delthyrium - and a brachial (dorsal) valve carrying the lophophore support.','Pedicle = stalk that anchors the animal. Lophophore = coiled feeding organ; its calcareous support is called the brachidium.','IIT-JAM Geology 2021; IIT-JAM Geology 2022; IIT-JAM Geology 2024',true,3,1,646) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f019','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Brachiopods range from Cambrian to Recent but dominated Palaeozoic sea floors; Productus (spiny) and Spirifer (wide, wing-like hinge) are typical Late Palaeozoic genera.','After the end-Permian extinction bivalves largely took their place. Lingula survives today almost unchanged.',null,true,2,2,647) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f020','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','In bivalves the pallial line marks where the mantle was attached; an embayment in it, the pallial sinus, shows the animal had retractable siphons and burrowed.','Siphons are breathing and feeding tubes. A deep sinus means long siphons, so a deep burrower.','IIT-JAM Geology 2022',true,3,1,648) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f021','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Bivalve hinge types include taxodont (many small similar teeth, e.g. Arca, Nucula), heterodont (cardinal and lateral teeth, e.g. Venus) and schizodont (e.g. Trigonia).','Dentition = the pattern of hinge teeth that keeps the two valves aligned. It is a main basis of bivalve classification.',null,true,2,2,649) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f022','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Bivalve life habits: Mytilus lives attached by byssus threads, Pecten can swim by clapping its valves, Mya burrows deeply and Ostrea cements one valve to the sea floor.','Shell shape follows life habit. Byssus = bundle of tough threads used as an anchor.','IIT-JAM Geology 2022',true,2,2,650) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f023','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Inoceramus is a key Cretaceous zone bivalve; Trigonia is a Mesozoic genus common in the Jurassic of Kutch; rudists were Cretaceous reef-building bivalves that died out at the end of the Cretaceous.','Bivalves range from Cambrian to Recent but became dominant only in the Mesozoic and Cenozoic.',null,true,2,2,651) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f024','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','A gastropod shell is one unchambered coiled tube: the spire (older whorls) plus the large body whorl ending in the aperture, coiled around a central pillar called the columella. Range: Cambrian to Recent.','No chambers and no siphuncle - that separates a snail shell from a coiled cephalopod shell.',null,true,2,2,652) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f025','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Most gastropod shells coil dextrally (aperture on the right when the apex points up); Physa coils sinistrally, and Physa prinsepii is a typical fossil of the Deccan Inter-trappean beds.','Physa is a freshwater snail, so it shows the inter-trappean beds were laid in lakes between lava flows.','IIT-JAM Geology 2023',true,3,1,653) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f026','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','A cephalopod shell is divided by septa into chambers linked by a tube called the siphuncle; the chambered part is the phragmocone and the animal lives in the last (body) chamber.','The siphuncle moves liquid in and out of the chambers to control buoyancy, like ballast tanks. It is central in Nautilus but near the outer edge in ammonoids.','IIT-JAM Geology 2022',true,3,1,654) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f027','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Ammonoid sutures: goniatitic (simple zigzag, unfrilled lobes and saddles) - Devonian to Permian; ceratitic (frilled lobes, smooth saddles) - mainly Triassic; ammonitic (both frilled) - Jurassic and Cretaceous.','Suture = the line where a septum meets the shell wall. Saddles point to the aperture, lobes point away. Hook: G-C-A, in order of time and frilliness.','IIT-JAM Geology 2024',true,3,1,655) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f028','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Ammonoids ranged from the Devonian to the end of the Cretaceous; nautiloids appeared in the Late Cambrian, have simple gently curved sutures, and survive today as Nautilus.','Nautilus is the only living cephalopod with a coiled external shell, so it is the living model for how ammonite shells worked.','IIT-JAM Geology 2022',true,3,1,656) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f029','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Belemnites were squid-like cephalopods with an internal shell; the usual fossil is the solid, bullet-shaped calcite guard (rostrum). They are common in the Jurassic and Cretaceous and died out at the end-Cretaceous.','The guard acted as a counterweight at the tail end. Its calcite is widely used for oxygen-isotope sea-temperature studies.',null,true,2,2,657) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f030','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Trilobites (marine arthropods, Cambrian to Permian) are divided lengthwise into an axial lobe and two pleural lobes, and crosswise into cephalon, thorax and pygidium.','''Tri-lobe'' refers to the three lengthwise lobes, not head-body-tail. Cephalon = head shield; pygidium = tail shield.','IIT-JAM Geology 2021; IIT-JAM Geology 2022; IIT-JAM Geology 2024',true,3,1,658) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f031','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','The trilobite cephalon has a raised central glabella, cheeks crossed by facial sutures, compound eyes, and often genal spines drawn out from its rear corners.','Trilobites were among the first animals with eyes; the lenses were made of calcite. The glabella covered the stomach.','IIT-JAM Geology 2021',true,2,2,659) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f032','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Trilobites grew by moulting; the facial sutures were lines of weakness along which the old head shield split open.','Like crabs today, they shed the hard outer skeleton to grow. So one animal could leave many fossil moults.','IIT-JAM Geology 2022',true,2,2,660) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f033','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Trilobite facial sutures: proparian cuts the side margin in front of the genal angle, opisthoparian cuts the rear margin behind it, and gonatoparian passes through the genal angle.','Genal angle = rear corner of the cheek. ''Pro'' = in front, ''opistho'' = behind, ''gonato'' = at the angle.',null,true,2,2,661) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f034','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Classic Cambrian trilobite zones are Olenellus (Lower), Paradoxides (Middle) and Olenus (Upper); in India, Redlichia marks the Cambrian of the Salt Range and Spiti.','Trilobites are the main index fossils of the Cambrian because they evolved fast and had hard, easily preserved shields.',null,true,2,2,662) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f035','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Graptolites were colonial, mostly floating hemichordates; graptoloids are the prime zone fossils of the Ordovician and Silurian, usually preserved as carbon films in black shales.','They drifted across oceans and evolved quickly - ideal index fossils. A colony (rhabdosome) has branches (stipes) carrying cups (thecae).',null,true,3,1,663) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f036','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Graptolite evolution shows reduction of stipes: many-branched Dictyonema, four-stiped Tetragraptus, two-stiped Didymograptus (Ordovician), then single-stiped Monograptus (Silurian).','Hook: many - 4 - 2 - 1. Didymograptus looks like a tuning fork; Monograptus has cups on one side only.',null,true,2,2,664) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f037','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Regular echinoids (e.g. Cidaris) have five-fold radial symmetry with the anus inside the apical disc; irregular echinoids (e.g. Micraster, Hemiaster) are bilateral with the anus outside it.','Regular forms graze on the surface; irregular forms burrow, so they gained a front and a back. Echinoids are Ordovician to Recent; irregular ones appear in the Jurassic.','IIT-JAM Geology 2021',true,3,1,665) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f038','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','An echinoid test has five ambulacral areas pierced by pore pairs for the tube feet, alternating with five interambulacral areas; its jaw apparatus is called Aristotle''s lantern.','Tube feet are small water-filled ''legs'' used for moving and breathing. Echinoderm plates are made of calcite, each plate a single crystal.','IIT-JAM Geology 2024',true,2,2,666) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f039','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Crinoids (''sea lilies'') are stalked echinoderms with a stem, calyx and arms; their broken stem pieces build Palaeozoic crinoidal limestones. Blastoids such as Pentremites died out in the Permian.','Crinoids look like plants but are animals. They were most abundant in the Palaeozoic, though some still live today.',null,true,2,2,667) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f040','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Rugose corals (septa inserted in fours) and tabulate corals (colonial, with strong tabulae) are Ordovician to Permian; scleractinian corals (septa in sixes) range from Triassic to Recent.','Rugosa and Tabulata died in the end-Permian extinction; all modern reef corals are scleractinians. Rugose corals are also called tetracorals, scleractinians hexacorals.',null,true,3,1,668) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f041','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Coral skeleton parts: septa (vertical radial plates), tabulae (horizontal floors) and dissepiments (small curved plates). Favosites (honeycomb coral) and Halysites (chain coral) are tabulate; Zaphrentis and Calceola are rugose.','Each polyp sits in a cup called a corallite. Calceola is the Devonian ''slipper coral'' with a lid.','IIT-JAM Geology 2024',true,2,2,669) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f042','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Foraminifera are single-celled, mostly marine protists whose tests are agglutinated (cemented grains), microgranular (fusulinids), porcelaneous (miliolids) or glassy hyaline calcite (rotaliids, globigerinids).','Wall type is the first step in classifying forams. They range from Cambrian to Recent and are the most used microfossils.',null,true,3,1,670) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f043','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Many foraminifera are dimorphic: the megalospheric form has a large first chamber (proloculus) but a small test; the microspheric form has a tiny proloculus but a large test.','The two forms come from alternating asexual and sexual generations. Nummulites shows this clearly.',null,true,2,2,671) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f044','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Fusulinids are spindle-shaped larger foraminifera restricted to the Carboniferous and Permian, which makes them excellent index fossils for the Late Palaeozoic.','They look like grains of wheat. They died out in the end-Permian extinction, so any fusulinid limestone is Late Palaeozoic.',null,true,3,1,672) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f045','geological-assistant','geological-assistant-m2','Morphology and time-ranges of fossil groups','Nummulites, a coin-shaped larger foraminifer, ranges from Paleocene to Oligocene and peaks in the Eocene; it builds the Eocene nummulitic limestones of Kutch, Jaisalmer, Subathu and Meghalaya.','''Nummulus'' = little coin. The Eocene sea that left these limestones was the shrinking Tethys.',null,true,3,1,673) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f046','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Ammonoid sutures grew more complex through time; in the Cretaceous many ammonites became uncoiled ''heteromorphs'' such as straight Baculites, hooked Scaphites and helical Turrilites.','More folded septa are thought to have strengthened the shell against water pressure. Turrilites looks like a snail but has chambers and sutures.',null,true,2,2,674) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f047','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Bivalves replaced brachiopods as the main shelled sea-floor animals after the end-Permian extinction; in the Mesozoic, burrowing bivalves with siphons diversified strongly as shell-crushing predators increased.','Hiding in the sediment is a defence. This rise of predators and burrowers is called the Mesozoic marine revolution.','IIT-JAM Geology 2022',true,2,2,675) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f048','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Mammals arose from mammal-like reptiles (therapsids, of the cynodont group) in the Late Triassic, stayed small through the Mesozoic, and diversified rapidly in the Paleocene and Eocene.','Dinosaurs held the big-animal roles until 66 million years ago. Their extinction left empty niches for mammals to fill.',null,true,3,1,676) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f049','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Textbook horse lineage: Eohippus or Hyracotherium (Eocene), Mesohippus (Oligocene), Merychippus (Miocene), Pliohippus (Pliocene), Equus (Pleistocene to Recent) - evolved mainly in North America.','Hook: E-M-M-P-E, one genus per epoch. Eohippus means ''dawn horse'' and was only the size of a fox.','IIT-JAM Geology 2021',true,3,1,677) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f050','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Horse evolution shows increase in body size, reduction of toes from four (front foot of Eohippus) to one, a longer face and limbs, and high-crowned (hypsodont) grazing teeth.','Forests gave way to open grassland, so horses became fast runners and grass eaters. Gritty grass wears teeth, so tall crowns helped.',null,true,3,1,678) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f051','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Mesohippus had three toes on each foot; Merychippus was the first grazing horse with high-crowned teeth; Pliohippus was the first one-toed horse.','Browsing = eating soft leaves (low-crowned teeth). Grazing = eating grass (high-crowned teeth). The switch came in the Miocene.',null,true,2,2,679) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f052','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Textbook elephant lineage: Moeritherium (Eocene of Fayum, Egypt), Palaeomastodon (Oligocene), Gomphotherium or Trilophodon (Miocene), Stegodon, then Elephas and Mammuthus (Pleistocene).','Moeritherium was pig-sized with no trunk. Proboscideans started in Africa and later spread to Asia, Europe and America.',null,true,3,1,680) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f053','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Elephant evolution trends: bigger body, nose and upper lip lengthened into a trunk, second incisors became tusks, the jaw shortened, and molars grew larger with more cross-ridges (plates).','A heavy head on a short neck cannot reach the ground, so the trunk does the reaching. More enamel ridges grind tough grass better.',null,true,3,1,681) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f054','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Hominin sequence: Australopithecus (Africa), Homo habilis (traditionally the first stone-tool maker), Homo erectus (Java and Peking Man, used fire), Homo sapiens; brain size rose from about 450 to about 1350 cc.','Upright walking came first, big brains later. Homo erectus was the first to spread out of Africa.',null,true,3,1,682) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f055','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','Key hominin finds: ''Taung child'' (Australopithecus africanus, Raymond Dart, South Africa, 1924); ''Lucy'' (Australopithecus afarensis, Ethiopia, 1974); Java Man (Homo erectus, Eugene Dubois, 1891); Homo habilis from Olduvai Gorge, Tanzania.','Africa holds the oldest hominins, which is why it is called the cradle of humankind. Java Man was first named Pithecanthropus erectus.',null,true,2,2,683) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f056','geological-assistant','geological-assistant-m2','Evolutionary changes in molluscs and mammals in geological time','India''s best-known ancient hominin fossil is the ''Narmada Man'' skull cap, found at Hathnora in the Narmada valley (Madhya Pradesh) by Arun Sonakia of GSI in 1982.','It came from Middle Pleistocene river gravels with stone tools. It is classed as Homo erectus or archaic Homo sapiens.',null,true,2,2,684) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f057','geological-assistant','geological-assistant-m2','Principles of evolution','Darwin''s theory of natural selection (''On the Origin of Species'', 1859) says heritable variations that improve survival and reproduction accumulate over generations; A. R. Wallace reached the same idea independently.','More young are born than can survive, so the better-fitted leave more offspring. Fossils give the time dimension of this change.',null,true,3,1,685) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f058','geological-assistant','geological-assistant-m2','Principles of evolution','Lamarck (1809) proposed evolution by inheritance of acquired characters through use and disuse of organs - a mechanism now rejected.','His example: giraffes stretching their necks and passing longer necks to their young. Changes gained in life are not passed on through genes.',null,true,2,2,686) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f059','geological-assistant','geological-assistant-m2','Principles of evolution','Neo-Darwinism (the Modern Synthesis) joins natural selection with Mendelian genetics: mutation and gene recombination supply the variation, and selection acts on populations. Hugo de Vries proposed the mutation theory in 1901.','Darwin did not know how variation arises or is inherited. Genetics filled that gap.',null,true,2,2,687) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f060','geological-assistant','geological-assistant-m2','Principles of evolution','Cope''s rule: body size tends to increase within an evolving lineage over geological time, as seen in horses and elephants.','Fox-sized Eohippus to modern horse is the standard example. It is a trend with exceptions, not a strict law.',null,true,3,1,688) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f061','geological-assistant','geological-assistant-m2','Principles of evolution','Dollo''s law: evolution is irreversible - a complex structure once lost is not regained in its original form.','Whales went back to the sea but did not regain gills; they still breathe with lungs.',null,true,3,1,689) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f062','geological-assistant','geological-assistant-m2','Principles of evolution','Punctuated equilibrium (Eldredge and Gould, 1972): species stay almost unchanged for long periods (stasis), with change concentrated in brief speciation events - the opposite of phyletic gradualism.','It explains why fossil species often appear suddenly with few intermediate forms. Gradualism expects slow, steady change instead.',null,true,3,1,690) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f063','geological-assistant','geological-assistant-m2','Principles of evolution','Adaptive radiation is the rapid diversification of one ancestral group into many ways of life, e.g. mammals in the early Cenozoic after the dinosaurs died out.','Empty niches after an extinction are quickly filled. Darwin''s finches are the living example.',null,true,2,2,691) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f064','geological-assistant','geological-assistant-m2','Principles of evolution','Convergent evolution gives unrelated groups similar shapes for similar lifestyles, e.g. ichthyosaurs (reptiles), sharks (fish) and dolphins (mammals); look-alike shells from unrelated stocks are called homeomorphs.','Same problem, same solution: fast swimming needs a streamlined body. Look-alike fossils from different groups can mislead correlation.',null,true,2,2,692) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f065','geological-assistant','geological-assistant-m2','Principles of evolution','Homologous organs share a common origin but differ in use (human arm, bat wing, whale flipper); analogous organs do the same job but arose separately (bird wing, insect wing).','Homology points to common ancestry (divergent evolution). Analogy points to convergent evolution.',null,true,3,1,693) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f066','geological-assistant','geological-assistant-m2','Principles of evolution','Haeckel''s biogenetic law says ''ontogeny recapitulates phylogeny'': the growth stages of an individual repeat the history of its ancestors. Ammonoid inner whorls with simpler sutures were the classic fossil example.','Ontogeny = growth of one individual. Phylogeny = history of the group. Today it is treated as a loose tendency, not a strict law.',null,true,2,2,694) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f067','geological-assistant','geological-assistant-m2','Use of species and genera of foraminifera and echinodermata in biostratigraphic correlation','Planktonic foraminifera give the standard zonation of Cretaceous and Cenozoic marine rocks; Globotruncana marks the Late Cretaceous (as in the Cauvery basin) and died out at the Cretaceous-Paleogene boundary.','Floating forms spread across whole oceans and evolve fast. Globigerina and Globorotalia take over in the Cenozoic.',null,true,3,1,695) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f068','geological-assistant','geological-assistant-m2','Use of species and genera of foraminifera and echinodermata in biostratigraphic correlation','Planktonic foraminifera first appear in the Jurassic. Cenozoic tropical zones are numbered P (Paleogene) and N (Neogene); the first appearance of Orbulina (the ''Orbulina datum'') lies near the base of the Middle Miocene.','A datum is a first or last appearance of a species used as a time line. Orbulina is a simple sphere, easy to spot.',null,true,2,2,696) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f069','geological-assistant','geological-assistant-m2','Use of species and genera of foraminifera and echinodermata in biostratigraphic correlation','Among larger benthic foraminifera, Orbitoides marks the Late Cretaceous, Assilina, Alveolina and Discocyclina the Eocene, Lepidocyclina the Oligocene-Miocene and Miogypsina the Miocene.','Larger forams lived in warm shallow seas and are used where planktonic forms are scarce, as in the shelf limestones of Kutch.',null,true,3,1,697) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f070','geological-assistant','geological-assistant-m2','Use of species and genera of foraminifera and echinodermata in biostratigraphic correlation','Benthic (bottom-living) foraminifera are tied to particular facies, so they are used mainly to read old water depth and environment; a higher planktonic-to-benthic ratio means deeper, more open sea.','Planktonic forms rain down everywhere in open sea, but few bottom forms live in deep water. So the ratio rises offshore.',null,true,2,2,698) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f071','geological-assistant','geological-assistant-m2','Use of species and genera of foraminifera and echinodermata in biostratigraphic correlation','The heart-urchin Micraster shows gradual evolutionary change through the Upper Cretaceous Chalk of England and is used to zone it (Rowe, 1899).','It is the textbook case of slow, step-by-step evolution in one lineage, tied to deeper burrowing.',null,true,2,2,699) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f072','geological-assistant','geological-assistant-m2','Use of species and genera of foraminifera and echinodermata in biostratigraphic correlation','The stemless crinoids Marsupites and Uintacrinus are short-ranged, widespread zone fossils of the Upper Cretaceous Chalk.','Being free-floating or free-lying, they spread widely. Most other echinoderms are tied to one facies, so they are used only for local zoning.',null,true,1,3,700) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f073','geological-assistant','geological-assistant-m2','Use of species and genera of foraminifera and echinodermata in biostratigraphic correlation','In India, echinoids serve as local guide fossils of the marine Cretaceous: Hemiaster in the Bagh Beds of the Narmada valley and Stigmatopygus elatus in the Ariyalur Group of the Cauvery basin.','Echinoids live on or in the sea bed, so they do not spread as widely as floating forms. They work best within one basin.',null,false,1,3,701) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f074','geological-assistant','geological-assistant-m2','Use of species and genera of foraminifera and echinodermata in biostratigraphic correlation','The Um Sohryngkew River section in Meghalaya exposes a marine Cretaceous-Paleogene boundary, marked by a turnover of planktonic foraminifera and an iridium anomaly.','It is India''s best-known marine record of the end-Cretaceous extinction. Cretaceous planktonic forams vanish at the boundary clay.',null,true,2,2,702) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f075','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','The Siwalik Group (Middle Miocene to Early Pleistocene) is a freshwater molasse famous for its mammal fossils - elephants, horses, giraffes, pigs, apes - first described by Falconer and Cautley in ''Fauna Antiqua Sivalensis''.','Molasse = river sediment shed from a rising mountain chain. There are no dinosaurs: the beds are far too young.','IIT-JAM Geology 2024',true,3,1,703) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f076','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Lower Siwalik (Kamlial-Chinji) fauna includes the pig Listriodon, Deinotherium, Gomphotherium (Trilophodon), the giraffid Giraffokeryx and the ape Sivapithecus.','These are forest and woodland animals, showing a warm, humid climate in the Miocene foothills.',null,true,2,2,704) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f077','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','The three-toed horse Hipparion is the characteristic fossil of the Middle Siwalik (Nagri and Dhok Pathan formations); it migrated in from North America.','Its arrival (the ''Hipparion datum'') is used to correlate Late Miocene land deposits across the Old World.',null,true,3,1,705) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f078','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Upper Siwalik (Tatrot-Pinjor) fauna is of modern type: Equus, Elephas, Bos or Leptobos, Camelus, Stegodon, Hippopotamus (Hexaprotodon) and the giant tortoise Colossochelys atlas.','True one-toed horse, true elephant and true cattle arrive together. Hook: Equus-Elephas-Bos = Pinjor.',null,true,3,1,706) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f079','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Stegodon, an extinct elephant relative with low-crowned molars bearing roof-like ridges, is common in the Upper Siwalik; Stegodon ganesa had enormous, long tusks.','''Stegodon'' means ''roof tooth''. It links the mastodon-like forms to true elephants in textbook lineages.',null,true,2,2,707) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f080','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Sivatherium giganteum was a huge, short-necked giraffid with horn-like ossicones, known from the Upper Siwalik.','The name means ''Shiva''s beast''. It looked more like a giant moose than a modern giraffe.',null,true,2,2,708) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f081','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Ramapithecus, described by G. E. Lewis from the Siwaliks at Haritalyangar (Himachal Pradesh), was once thought a human ancestor; it is now merged with Sivapithecus, a relative of the orangutan.','Only jaw pieces were known at first, and they looked human-like. Better skulls later showed an orangutan-like face.',null,true,3,1,709) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f082','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','The Siwalik Fossil Park at Saketi (Sirmaur district, Himachal Pradesh), run by the Geological Survey of India, displays life-size models of Siwalik mammals at a real fossil site.','Saketi lies in the Markanda valley, where Upper Siwalik beds are rich in vertebrate fossils.',null,true,1,3,710) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f083','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Lower Gondwana (Permian) rocks carry the Glossopteris flora: Glossopteris, Gangamopteris, Vertebraria, Schizoneura, Noeggerathiopsis and Sphenophyllum.','This cool-climate flora followed the Talchir glaciation and formed India''s main coal seams.','IIT-JAM Geology 2021',true,3,1,711) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f084','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Glossopteris is a tongue-shaped leaf with a distinct midrib and net-like veins; Gangamopteris is similar but has no midrib and dominates the oldest beds (Talchir and Karharbari).','''Glossa'' = tongue. Hook: Gangamopteris came first and has no midrib; Glossopteris takes over in the Barakar and Raniganj.',null,true,3,1,712) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f085','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Vertebraria is the root-like underground axis of the Glossopteris plant, while Glossopteris, Dicroidium and Ptilophyllum are names for leaves.','Fossil plant parts found separately get separate names. Vertebraria looks like a row of vertebrae, hence the name.','IIT-JAM Geology 2022',true,2,2,713) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f086','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Separate plant organs carry separate names in the Gondwana flora: Dadoxylon is fossil wood (stem), and Samaropsis and Cordaicarpus are detached seeds.','A whole plant is rarely fossilised in one piece. So leaf, wood, root and seed each got their own genus name.','IIT-JAM Geology 2022; IIT-JAM Geology 2023',true,2,2,714) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f087','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Glossopteris was a seed fern (pteridosperm, a gymnosperm), not a true fern; its remains formed the Permian coal of the Barakar and Raniganj formations.','Seed ferns had fern-like leaves but reproduced by seeds. Growth rings in Gondwana wood show a seasonal, cool-temperate climate.','IIT-JAM Geology 2024',true,3,1,715) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f088','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','The Glossopteris flora occurs in India, Australia, South Africa, South America and Antarctica - key fossil evidence that these lands once formed Gondwanaland.','Its seeds were too heavy to cross oceans. Wegener used this distribution as evidence for continental drift.',null,true,3,1,716) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f089','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Dicroidium (earlier called Thinnfeldia), a seed fern with forked fronds, typifies the Triassic or ''Middle'' Gondwana, e.g. the Panchet and Parsora beds.','After the end-Permian extinction the Glossopteris flora declined and Dicroidium replaced it across Gondwanaland.',null,true,2,2,717) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f090','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Upper Gondwana (Jurassic to Early Cretaceous) rocks carry the Ptilophyllum flora of cycad-like plants, conifers and ferns: Ptilophyllum, Otozamites, Williamsonia, Brachyphyllum, Araucarites and Cladophlebis.','Classic localities: Rajmahal Hills, Jabalpur, Kota, Athgarh, Sriperumbudur and Kutch. Hook: Lower = Glossopteris, Middle = Dicroidium, Upper = Ptilophyllum.',null,true,3,1,718) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f091','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Birbal Sahni reconstructed the Williamsonia sewardiana plant and described Pentoxylon from the Rajmahal Hills; he founded the palaeobotany institute at Lucknow in 1946.','Williamsonia is the ''flower'' of the plant that bore Ptilophyllum leaves. Sahni is called the father of Indian palaeobotany.',null,true,2,2,719) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f092','geological-assistant','geological-assistant-m2','Siwalik vertebrate fauna and Gondwana flora','Lepidodendron and Sigillaria (giant club-mosses) and Calamites (giant horsetail) formed the Carboniferous coal forests of Europe and North America; they are not part of the Glossopteris flora.','Northern coal is Carboniferous and tropical; Indian Gondwana coal is Permian and cool-climate. Stigmaria is the root of Lepidodendron.',null,true,2,2,720) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f093','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','Stromatolites are laminated mounds built when mats of cyanobacteria (blue-green algae) trap and bind sediment; they are the commonest evidence of Precambrian life.','They are layered structures made by microbes, not body fossils. Their oxygen-making builders slowly changed the early atmosphere.','IIT-JAM Geology 2024',true,3,1,721) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f094','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','The oldest widely accepted stromatolites, about 3.5 billion years old, are in the Pilbara craton of Western Australia; living ones grow today at Shark Bay.','This shows microbial life existed in the early Archaean. Shark Bay is too salty for grazing snails, so the mats survive.',null,true,2,2,722) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f095','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','The Gunflint Chert of Ontario, Canada (about 1.9 billion years old) gave the first well-preserved Precambrian microfossils, described by Tyler and Barghoorn in 1954.','Chert (fine silica) seals in tiny cells before they decay. Older microfossils are reported from the Fig Tree cherts of South Africa (over 3 billion years).',null,true,2,2,723) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f096','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','The earliest life was prokaryotic (cells without a nucleus). Oxygen released by cyanobacteria caused the Great Oxidation Event about 2.4 billion years ago; eukaryotes (cells with a nucleus) appear later, in the Proterozoic.','Banded iron formations formed as this oxygen combined with dissolved iron in the sea. Complex cells needed an oxygen-bearing world.',null,true,2,2,724) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f097','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','In India stromatolites are common in Proterozoic carbonates of the Vindhyan, Cuddapah, Kaladgi, Chhattisgarh and Aravalli basins; at Jhamarkotra (Udaipur) they host rock phosphate.','Form-types such as Collenia and Conophyton (cone-shaped) help in broad correlation of these otherwise unfossiliferous basins.',null,true,3,1,725) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f098','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','Stromatolites were most abundant and varied in the Proterozoic and declined sharply towards its end, probably because newly evolved animals grazed and burrowed the microbial mats.','Today they survive only where grazers cannot live, such as very salty lagoons.',null,true,2,2,726) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f099','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','Archaean stromatolites occur in the Dharwar Supergroup of Karnataka (Chitradurga, Sandur, Shimoga belts) and the Iron Ore Group of Odisha - among the oldest evidence of life in India.','These Archaean carbonates are over 2.5 billion years old, far older than the Vindhyan or Cuddapah stromatolites.',null,false,1,3,727) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f100','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','Acritarchs are organic-walled microfossils of uncertain affinity (probably cysts of planktonic algae); they are the main biostratigraphic tool for the Proterozoic and are also common in the Lower Palaeozoic.','''Acritarch'' means ''of uncertain origin''. They are freed from rock by dissolving it in acid, like pollen.',null,true,2,2,728) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f101','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','The Ediacaran fauna - soft-bodied animals such as Dickinsonia, Spriggina and Charnia - lived just before the Cambrian (about 575 to 539 million years ago) and is named after the Ediacara Hills of South Australia.','These are the oldest large, many-celled animals. They had no shells, so they are preserved only as impressions in sandstone.',null,true,3,1,729) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f102','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','A 2021 report of Dickinsonia from Bhimbetka (Upper Vindhyan, Madhya Pradesh) was disproved in 2023: the ''fossil'' was a decayed beehive, and the original authors accepted this.','A re-visit found the impression peeling off the rock, with wax still present. A reminder that pseudofossils (false fossils) can fool experts.',null,true,1,3,730) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f103','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','Vindhyan rocks yield Precambrian carbonaceous megafossils: disc-shaped Chuaria, sausage-shaped Tawuia, and coiled Grypania from the Rohtas Formation, regarded as an early eukaryote.','Eukaryote = cell with a nucleus. These thin carbon films are visible to the naked eye, unlike most Precambrian fossils.',null,true,2,2,731) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f104','geological-assistant','geological-assistant-m2','Evidence of life in Precambrian times','The base of the Cambrian is defined by the first appearance of the burrow trace fossil Treptichnus pedum; small shelly fossils of this age occur in the Tal Formation of the Lesser Himalaya.','A complex burrow shows animals that could dig in three dimensions. The underlying Krol beds are Ediacaran in age.',null,true,2,2,732) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f105','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Microfossils grouped by wall material: calcareous (foraminifera, ostracods, coccoliths), siliceous (radiolaria, diatoms), phosphatic (conodonts) and organic-walled (spores, pollen, dinoflagellate cysts, acritarchs).','The wall material decides the lab method: acids destroy calcareous forms but free the organic-walled and siliceous ones.',null,true,3,1,733) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f106','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Ostracods are tiny bivalved crustaceans with a calcareous carapace, living since the early Palaeozoic in marine, brackish and fresh water - useful for salinity studies and non-marine correlation.','They look like microscopic clams but are relatives of shrimps. Different species prefer different salinity.',null,true,2,2,734) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f107','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Radiolaria are marine planktonic protists with an opaline silica skeleton (Cambrian to Recent): Spumellaria are spherical, Nassellaria cone- or helmet-shaped. They form deep-sea ooze and chert, as in the ophiolite belts of Ladakh, Nagaland and Andaman.','Silica survives below the depth where carbonate dissolves, so radiolarian chert marks old deep ocean floor.',null,true,2,2,735) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f108','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Diatoms are single-celled algae with a two-part silica shell (frustule), round (centric) or elongate (pennate), found in marine and fresh water mainly from the Cretaceous onward; their deposits form diatomite.','The frustule fits together like a pill-box. Being plants, they need light and live only in the sunlit upper water.',null,true,2,2,736) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f109','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Conodonts are tooth-like microfossils of calcium phosphate (apatite) from an extinct eel-like chordate, ranging from Cambrian to Triassic; their colour (Conodont Alteration Index) records how strongly the rock was heated.','They are key index fossils for Palaeozoic and Triassic marine rocks. Pale = cool, black = heated, so they show if oil could survive.',null,true,3,1,737) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f110','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','The Permian-Triassic boundary is defined by the first appearance of the conodont Hindeodus parvus; in India it is studied with conodonts at Guryul Ravine (Kashmir) and in Spiti.','Ammonoids like Otoceras were used earlier, but conodonts are found in more sections and give finer zones.',null,true,2,2,738) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f111','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Spores and pollen have a tough sporopollenin wall and are carried into both land and sea deposits, so palynology is the main tool for correlating non-marine beds such as Gondwana coal seams.','Palynology = study of spores and pollen. Striped two-sac (striate bisaccate) pollen of the Glossopteris plants is typical of the Indian Permian.',null,true,3,1,739) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f112','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Dinoflagellate cysts are organic-walled marine plankton fossils useful from the Late Triassic onward; chitinozoans are flask-shaped organic-walled microfossils of the Ordovician to Devonian.','Both are studied on the same slides as spores and pollen, so together they are called palynomorphs.',null,true,1,3,740) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f113','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Calcareous nannofossils (coccoliths) are calcite plates of planktonic algae, only a few micrometres across, ranging from Late Triassic to Recent; they are the main ingredient of chalk.','They are so small that a tiny chip of rock holds thousands. Star-shaped discoasters are typical Cenozoic forms.',null,true,2,2,741) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f114','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Microfossils suit oil exploration because they are abundant and survive whole in small drill cuttings, giving the age, correlation and depositional depth of subsurface beds.','Big fossils are broken by the drill bit; microfossils are not. Foraminifera, nannofossils and palynomorphs are the main groups used in Indian basins.',null,true,3,1,742) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f115','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Freshwater microfossils - charophyte fruiting bodies (gyrogonites of the alga Chara) and ostracods - are typical of the Lameta and Deccan Inter-trappean beds.','They prove these beds were laid in lakes and ponds, not in the sea. They also help fix the latest Cretaceous to earliest Paleocene age.',null,true,2,2,743) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f116','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','The marine Cretaceous of the Cauvery basin (Uttattur, Trichinopoly, Ariyalur groups) is rich in foraminifera; the Ariyalur Group carries Globotruncana and larger forms such as Orbitoides, Siderolites and Lepidorbitoides.','These are Late Cretaceous (Campanian-Maastrichtian) markers. The Cauvery basin is India''s reference area for Cretaceous marine microfossils.',null,true,2,2,744) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f117','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Kutch is the reference area for Indian Tertiary larger foraminifera: Nummulites, Assilina, Alveolina and Discocyclina in the Eocene; Nummulites fichteli and Lepidocyclina in the Oligocene; Miogypsina in the Lower Miocene.','Shallow warm shelf limestones there are packed with larger forams. Similar zones are used in the Mumbai offshore basin.',null,true,2,2,745) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f118','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','The Sylhet Limestone (Jaintia Group) of Meghalaya and Assam is a Paleocene-Eocene shelf limestone rich in Nummulites, Assilina, Alveolina and Discocyclina.','It is the nummulitic limestone of north-east India, quarried for cement. It was laid on a shallow shelf at the edge of the Shillong Plateau.',null,true,3,1,746) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f119','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','In the Upper Assam oilfields the oil-bearing Barail and Tipam beds are poor in marine microfossils, so subsurface correlation there relies mainly on palynology (spores and pollen).','These sands were laid by rivers and deltas, where forams are rare but pollen is plentiful.',null,false,1,3,747) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f120','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','The Andaman-Nicobar islands (for example Neill and Havelock islands) expose India''s best Neogene deep-water marine sequence, rich in planktonic foraminifera, radiolaria and calcareous nannofossils.','Open-ocean plankton settled here, away from river mud. So Indian Neogene planktonic zones are tied to Andaman sections.',null,true,2,2,748) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f121','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','Kerala''s Quilon Limestone (Lower Miocene, Burdigalian; type area Padappakkara near Kollam) carries larger foraminifera - Miogypsina, Lepidocyclina, Austrotrillina and Pseudotaberina (Orbiculina) malabarica - with corals and molluscs.','Miogypsina fixes the Early Miocene age. The fauna records a warm, shallow sea over the Kerala coast.',null,true,3,1,749) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f122','geological-assistant','geological-assistant-m2','Different microfossil groups and their distribution in India','The lignite and carbonaceous clays of Kerala''s Warkalli Formation are poor in shelly fossils; they are dated as Miocene (to Mio-Pliocene) mainly from spores and pollen, which show warm, humid coastal vegetation.','Lignite forms from land plants in swamps, so pollen is the fossil to look for. The marine Quilon beds below are dated by forams instead.',null,true,2,2,750) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f001','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','The Spiti valley in the Tethys Himalaya holds India''s most complete marine fossil-bearing sequence, running from the Cambrian to the Cretaceous.','Spiti lay under the Tethys sea for most of that time, so beds piled up with few breaks. It is the reference section for Himalayan stratigraphy.',null,true,3,1,751) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f002','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','The Cambrian of Spiti is the Haimanta Group; its upper beds in the Parahio valley carry trilobites.','Haimanta means ''snow-covered''. Trilobites (extinct sea arthropods) prove the Cambrian age.',null,true,2,2,752) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f003','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','The Muth Quartzite of Spiti is a hard, white, almost unfossiliferous quartzite of Devonian age (possibly starting in the late Silurian).','It is a clean shore sand turned to quartzite. White and barren, it is an easy marker between fossil-rich units.',null,true,2,2,753) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f004','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','In Spiti the Carboniferous is the Kanawar Group: Lipak Formation (limestone) below and Po Formation (shale and quartzite, ending in Fenestella Shales) above.','Fenestella is a lace-like bryozoan (tiny colony animal). Order hook: Lipak is Lower, Po is on top.',null,true,1,3,754) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f005','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','The Kuling Group is the Permian of Spiti; its upper part is the black Productus Shales.','Productus is a spiny brachiopod (lamp shell) typical of Permian seas. The Triassic Lilang beds follow directly above.',null,true,2,2,755) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f006','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','Cambrian of the Salt Range, bottom to top: Purple Sandstone, Neobolus Shales, Magnesian Sandstone, Salt Pseudomorph Shales.','Hook: P-N-M-S. Neobolus is a small brachiopod. Salt pseudomorphs are clay casts of salt cubes from a drying lagoon.',null,true,3,1,756) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f007','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','The Saline Series of the Salt Range (rock salt, gypsum, marl; mined at Khewra) lies below the Cambrian Purple Sandstone and is latest Precambrian to earliest Cambrian.','Its age was argued for decades (Cambrian or Eocene). It is now taken as lying in normal order under the Cambrian.',null,true,2,2,757) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f008','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','In the Salt Range the Ordovician to Middle Carboniferous is missing: the glacial Talchir Boulder Bed rests straight on Cambrian rocks.','The area stayed above sea level, so nothing was laid down. This big gap (unconformity) is a favourite exam point.',null,true,2,2,758) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f009','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','Late Palaeozoic of the Salt Range, bottom to top: Boulder Bed (glacial, Talchir equivalent), Speckled Sandstone, Productus Limestone (Permian).','Ice first, then a sandy shallow sea, then a clear warm sea full of brachiopods. Hook: Boulder - Speckled - Productus.',null,true,3,1,759) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f010','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','In Kashmir the Syringothyris Limestone is Lower Carboniferous and the Fenestella Shales above it are Middle Carboniferous.','Both are named after their index fossils: Syringothyris is a brachiopod, Fenestella a bryozoan.',null,true,3,1,760) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f011','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','The Panjal Volcanics of Kashmir are the Agglomeratic Slate (below) and the Panjal Trap basalt flows (above), of Late Carboniferous to Permian age.','Explosive ash and fragments came first, then quiet lava. Do not confuse with the far younger Deccan Traps.','TNPSC Geology (Degree Std, CUGE/19) 2019; IIT-JAM Geology 2017',true,3,1,761) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f012','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','In Kashmir the Gangamopteris beds (Lower Gondwana plants) lie above the Panjal volcanics and below the marine Upper Permian Zewan beds.','Land plants under dated sea beds prove the Lower Gondwana flora is Permian. This ties Peninsular and Himalayan stratigraphy together.',null,true,3,1,762) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f013','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','The Guryul Ravine near Srinagar exposes a continuous Permian-Triassic boundary section, from the Zewan Formation up into the Khunamuh Formation.','Few places on Earth show this boundary without a break. It records the biggest mass extinction.',null,true,1,3,763) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f014','geological-assistant','geological-assistant-m2','Stratigraphy of the Palaeozoic formations of India','The Umaria marine bed (Madhya Pradesh) is a thin Lower Permian marine layer with Productus, lying just above the Talchir beds inside a Gondwana basin.','It records a short invasion of the sea into the land-locked troughs. Peninsular India otherwise has almost no marine Palaeozoic.',null,true,2,2,764) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f015','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Triassic of Spiti is the Lilang Group: thick limestone and shale, very rich in ammonoids.','Named after Lilang village. Ammonoids (coiled cephalopod shells) evolved fast, so the Spiti Triassic is zoned in fine detail.',null,true,3,1,765) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f016','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Otoceras zone, with Otoceras woodwardi, is the lowest Triassic zone of Spiti and marks the Permian-Triassic boundary there.','It sits right on the Permian Productus Shales. Hook: O for Otoceras, O for opening of the Triassic.',null,true,3,1,766) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f017','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Kioto (Megalodon) Limestone tops the Triassic of Spiti and continues from the latest Triassic into the Lower-Middle Jurassic.','Megalodon here is a thick-shelled bivalve, not the shark. The cliff-forming limestone crosses the Triassic-Jurassic boundary.',null,true,2,2,767) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f018','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Spiti Shales are black Upper Jurassic shales (reaching the earliest Cretaceous) with ammonite-bearing concretions called saligrams.','Saligrams are round nodules that split to show an ammonite. They are collected as sacred stones.',null,true,3,1,768) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f019','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Above the Spiti Shales come the Giumal Sandstone (Lower Cretaceous) and the Chikkim limestone and shale (Upper Cretaceous).','These are the last sea beds of Spiti before the Tethys closed. Hook going up: Spiti - Giumal - Chikkim.',null,true,2,2,769) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f020','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The marine Jurassic of Kutch has four classical series, oldest to youngest: Patcham, Chari, Katrol, Umia.','Hook: ''Please Come Kutch, Uncle''. The sea entered Kutch from the west in the Middle Jurassic.','UPSC Geologist Exam 2018 (Geology Paper I)',true,3,1,770) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f021','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Kutch ages: Patcham is Bathonian, Chari is Callovian-Oxfordian, Katrol is Kimmeridgian-Tithonian, and Umia runs from latest Jurassic into the Lower Cretaceous.','Patcham to Katrol are Middle to Upper Jurassic. Only the Umia crosses into the Cretaceous.',null,true,2,2,771) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f022','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Dhosa Oolite, a thin Oxfordian marker bed rich in ammonites, forms the top of the Chari Series in Kutch.','Oolite is limestone made of tiny round grains. This bed can be traced across Kutch, so it is used for correlation.',null,true,2,2,772) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f023','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Modern formation names for the Kutch Mesozoic (S.K. Biswas), oldest to youngest: Jhurio, Jumara, Jhuran, Bhuj. Roughly, Jhurio = Patcham and Jumara = Chari.','All four start with J-J-J-B. The Bhuj Formation is the sandy, plant-bearing Lower Cretaceous top (upper Umia).',null,true,2,2,773) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f024','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Umia (Bhuj) plant beds of Kutch carry the Upper Gondwana Ptilophyllum flora and are interbedded with marine beds holding ammonites.','Sea fossils give a firm date. So these beds help fix the age of the Upper Gondwana as Jurassic to Lower Cretaceous.',null,true,2,2,774) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f025','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Jurassic of Jaisalmer (Rajasthan), oldest to youngest: Lathi, Jaisalmer, Baisakhi, Bedesar formations. The Jaisalmer Formation is a golden-yellow limestone.','The yellow limestone is the stone of Jaisalmer fort. The Lathi beds below hold the fossil wood of Akal.',null,true,1,3,775) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f026','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Cretaceous of the Trichinopoly area (Cauvery basin), oldest to youngest: Uttatur, Trichinopoly, Ariyalur, with the Niniyur beds on top.','Hook: U-T-A-N. They record the great mid-Cretaceous sea flooding (transgression) of the east coast.','IIT-JAM Geology 2017',true,3,1,776) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f027','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Trichinopoly ages: Uttatur is Albian-Cenomanian, Trichinopoly is Turonian-Coniacian, Ariyalur is Campanian-Maastrichtian, and Niniyur is Danian (earliest Paleocene).','So the Cretaceous-Paleogene boundary lies between the Ariyalur and Niniyur. Ammonites stop at the top of the Ariyalur.',null,true,3,1,777) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f028','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Uttatur Group starts with coral-reef limestone (quarried at Dalmiapuram) and has clays with gypsum and phosphatic nodules; it is very rich in ammonites.','Reefs grew on the newly drowned shore, then mud covered them. The reef limestone feeds cement plants.',null,true,2,2,778) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f029','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Trichinopoly Group contains a shell limestone packed with white bivalve and gastropod shells, polished as the ornamental ''Trichinopoly marble''.','It is not a true marble, only a hard shelly limestone. Shell banks show a shallow, near-shore sea.',null,true,1,3,779) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f030','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Ariyalur Group has yielded dinosaur bones (Kallamedu beds); the Niniyur beds above carry Nautilus danicus and algae but no ammonites.','Ammonites and dinosaurs died out at the end of the Cretaceous. Their absence marks the Niniyur as Danian.',null,true,2,2,780) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f031','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Bagh Beds are marine Cretaceous (Cenomanian-Turonian) rocks of the lower Narmada valley: Nimar Sandstone at the base, then Nodular Limestone, then Coralline Limestone.','A narrow arm of the sea reached inland along the Narmada from the west. Hook going up: N-N-C.',null,true,3,1,781) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f032','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Bagh Bed fossils resemble those of Arabia and southern Europe, while Trichinopoly fossils are of Indo-Pacific type.','The two seas did not mix freely. A land barrier across the Peninsula kept the western (Tethyan) and eastern faunas apart.',null,true,2,2,782) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f033','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Lameta Beds are thin river and lake deposits of Maastrichtian (latest Cretaceous) age lying just below the Deccan Traps; they hold dinosaur bones and eggs. Type area: Lameta Ghat, Jabalpur.','They are ''infra-trappean'' (under the traps). Dinosaurs such as Titanosaurus prove a Cretaceous age for the base of the lavas.','IIT-JAM Geology 2017',true,3,1,783) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f034','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Deccan Traps are tholeiitic flood basalts erupted through fissures about 66 million years ago, across the Cretaceous-Paleogene boundary; they now cover about 500,000 square km.','''Trap'' comes from a Swedish word for stairs: flat flows weather into steps. Tholeiitic means a silica-saturated basalt.','TNPSC Geology (Degree Std, CUGE/19) 2019; IIT-JAM Geology 2017; JKPSC KAS Geology Paper I (KAS-12)',true,3,1,784) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f035','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Deccan lava pile is thickest (over 2000 m) near the west coast around Mumbai and the Western Ghats, and thins to the east and north.','The feeding fissures lay in the west. Thin edges far away, like Rajahmundry and Belgaum, are the tips of long flows.',null,true,2,2,785) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f036','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Deccan volcanism is linked to the Reunion hotspot, over which India passed as it drifted north; the Rajmahal Traps are linked to the Kerguelen hotspot.','A hotspot is a fixed hot plume under the moving plate. Deccan = Reunion, Rajmahal = Kerguelen is a common pairing question.',null,true,3,1,786) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f037','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Classical division of the Deccan Traps: Lower (eastern Madhya Pradesh), Middle (Malwa and central India), Upper (Mumbai and Kathiawar). Inter-trappean beds are common in Lower and Upper Traps, almost absent in the Middle.','The Middle Traps are the thickest yet have few sediment layers. That odd gap is the usual exam catch.',null,true,2,2,787) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f038','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Inter-trappean beds are thin freshwater lake sediments (chert, limestone, clay) between Deccan flows; the snail Physa prinsepii is the typical fossil.','Lakes formed on a cooled flow in quiet gaps, then the next flow buried them. Inter = between flows; infra = below all flows.',null,true,3,1,788) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f039','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The inter-trappean beds of Mumbai (Upper Traps) yield fossil frogs and tortoises; those near Rajahmundry have estuarine and marine fossils.','Frogs mean ponds on the lava plain. Sea shells at Rajahmundry show the east coast shoreline was close by.',null,true,1,3,789) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f040','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','Modern stratigraphy splits the Western Ghats lava pile (Deccan Basalt Group) into three subgroups, oldest to youngest: Kalsubai, Lonavala, Wai.','Flows are told apart by chemistry and marker beds. The Wai Subgroup includes the Ambenali and Mahabaleshwar formations.',null,true,1,3,790) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f041','geological-assistant','geological-assistant-m2','Stratigraphy of the Mesozoic formations of India','The Mahadek Formation is the Upper Cretaceous sandstone on the southern edge of the Shillong Plateau, Meghalaya; it hosts the Domiasiat uranium deposit.','It is the north-east record of the same Cretaceous sea flooding seen at Trichinopoly and Bagh.',null,true,2,2,791) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f042','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The name Gondwana was given by H.B. Medlicott in 1872, after the Gond kingdom of central India; it first appeared in print in 1876 (Feistmantel).','Gondwana means ''land of the Gonds''. Medlicott named the rocks; Suess later named the supercontinent after them.',null,true,3,1,792) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f043','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Gondwana Supergroup ranges from latest Carboniferous (Permo-Carboniferous) to Lower Cretaceous.','It starts with the Talchir ice age and ends just before the east-coast seas and the Deccan lavas arrive.',null,true,3,1,793) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f044','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Gondwana rocks are mainly river and lake sediments laid in fault-bounded, slowly sinking troughs (rift basins or grabens) within the Peninsular shield.','Sinking along faults let thick sediment and coal collect and saved them from later erosion.',null,true,3,1,794) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f045','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The main Gondwana basins follow river valleys: Damodar-Koel, Son-Mahanadi, Pranhita-Godavari and Satpura, with outliers in the Rajmahal hills and along the east coast.','Today''s rivers follow the old rift lines. That is why India''s coalfields sit along these same valleys.',null,true,3,1,795) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f046','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Two-fold: Lower Gondwana (Glossopteris flora; Talchir, Damuda, Panchet) and Upper Gondwana (Ptilophyllum flora; Mahadeva, Rajmahal, Jabalpur). Three-fold adds a Middle Gondwana for Triassic red beds (Panchet, Mahadeva).','Two-fold rests on plant fossils, so Panchet stays in the Lower. Three-fold rests on rock type and reptiles, as the Triassic beds are red and coal-free.','TNPSC Geology (Degree Std, CUGE/19) 2019',true,3,1,796) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f047','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Damodar valley sequence, oldest to youngest: Talchir, Karharbari, Barakar, Barren Measures, Raniganj (all Lower Gondwana), then Panchet and Supra-Panchet (Mahadeva).','Hook: ''Tall Kings Bring Big Rewards, Please''. The Damodar valley is the type area for the Lower Gondwana.','UPSC Geologist Exam 2018 (Geology Paper I); JKPSC KAS Geology Paper I (KAS-12)',true,3,1,797) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f048','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Damuda Group is the coal-bearing Permian part of the Lower Gondwana: Barakar, Barren Measures and Raniganj formations.','Damuda is the old spelling of the Damodar river. Coal seams lie in the Barakar and Raniganj, not in the Barren Measures.','TNPSC Geology (Degree Std, CUGE/19) 2019',true,3,1,798) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f049','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Talchir Formation is the base of the Gondwana: a glacial boulder bed (tillite) with striated, faceted boulders, overlain by green needle shales and varves, resting on Precambrian basement.','Scratched boulders and varves (thin yearly layers from meltwater lakes) are sure signs of ice. Named after Talchir in Odisha.','IIT-JAM Geology 2017',true,3,1,799) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f050','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Karharbari Formation (Lower Permian) lies above the Talchir, is best developed in the Giridih coalfield, carries good coal seams and is rich in Gangamopteris.','It is the first coal after the ice melted. The climate was still cool, so Gangamopteris outnumbers Glossopteris.',null,true,2,2,800) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f051','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Barakar Formation (Lower Permian) is India''s chief coal-bearing unit: sandstone, shale, fireclay and thick coal seams, including the prime coking coal of Jharia.','Warm, wet swamps gave thick peat. Named after the Barakar river. Think Barakar = bulk of Indian coal.','IIT-JAM Geology 2017',true,3,1,801) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f052','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Barren Measures lie between the Barakar and Raniganj formations and have no workable coal; in the Raniganj coalfield they are called the Ironstone Shales.','''Barren'' means barren of coal. The shales carry clay-ironstone (siderite) nodules instead.',null,true,3,1,802) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f053','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Raniganj Formation is Upper Permian and coal-bearing; rough equivalents are the Kamthi (Godavari-Wardha), Bijori (Satpura) and Himgir (Mahanadi) formations.','Same age, different basin, different local name. Raniganj coal is mostly non-coking and high in volatile matter.',null,true,2,2,803) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f054','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Panchet Formation is Lower Triassic: red and chocolate clays with greenish sandstones, no coal, and the reptile Lystrosaurus.','Red colour and no coal mean a drier climate. Lystrosaurus also occurs in South Africa and Antarctica, a link across Gondwanaland.',null,true,3,1,804) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f055','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Mahadeva Group of the Satpura basin has three formations, oldest to youngest: Pachmarhi, Denwa, Bagra; the massive Pachmarhi Sandstone forms the Pachmarhi scarps.','Named after the Mahadeva hills of Madhya Pradesh. Thick red and buff sandstones with no coal point to a dry climate.',null,true,2,2,805) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f056','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','In the Pranhita-Godavari basin the Maleri Formation (Upper Triassic red clays with reptiles) is followed by the Dharmaram and then the Kota Formation (Lower Jurassic, with fish and the dinosaur Barapasaurus).','Hook going up: M-D-K. The Kota has a thin limestone band with the fish Lepidotes.',null,true,2,2,806) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f057','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Rajmahal Formation of Jharkhand is a pile of Lower Cretaceous basalt flows (Rajmahal Traps) with inter-trappean plant beds carrying the Ptilophyllum flora.','It is an Upper Gondwana unit. Older books call it Jurassic; radiometric dates of about 117 million years put it in the Early Cretaceous.',null,true,3,1,807) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f058','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','The Jabalpur Formation (Upper Jurassic to Lower Cretaceous) of the Satpura-Jabalpur area is an Upper Gondwana unit of white clays and soft sandstones with thin coal.','It is the youngest Gondwana unit of central India. It lies below the Lameta Beds and the Deccan Traps.',null,true,2,2,808) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f059','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','East-coast Upper Gondwana outcrops include the Athgarh Sandstone (Cuttack), the Golapalli-Raghavapuram-Tirupati beds (Godavari) and the Sriperumbudur and Sivaganga beds (Tamil Nadu); some have marine layers.','The sea was starting to enter along the new east coast as India broke away. Marine fossils help date these beds.','TNPSC Geology (Degree Std, CUGE/19) 2019',true,2,2,809) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f060','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Gondwana climate story: glacial (Talchir), cool and wet (Karharbari), warm humid swamps (Barakar, Raniganj), dry semi-arid (Panchet, Mahadeva), then humid again (Upper Gondwana).','Read the rocks: boulder bed = ice, coal = wet swamp, red beds without coal = dry.','TNPSC Geology (Degree Std, CUGE/19) 2019',true,3,1,810) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f061','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Gondwana coal forms nearly all (about 98 per cent) of India''s coal resources; it is mainly bituminous, of drift origin, high in ash and low in sulphur.','Drift origin means plant matter was washed in with mud, so ash is high. The small remainder is Tertiary coal.',null,true,3,1,811) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f062','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Key Gondwana coalfields: Raniganj (West Bengal, India''s oldest, mined since 1774), Jharia and Bokaro (Jharkhand), Korba (Chhattisgarh), Singrauli (Madhya Pradesh-Uttar Pradesh), Talcher (Odisha), Singareni (Telangana).','Jharia gives prime coking coal. Singareni, in the Godavari valley, is the only major coalfield in South India.',null,true,3,1,812) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f063','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Gondwanaland (name by Eduard Suess) was the southern supercontinent of South America, Africa, Madagascar, India, Australia and Antarctica.','Suess took the name from the Indian Gondwana rocks, since the same rocks and fossils occur on all these lands.',null,true,3,1,813) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f064','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Evidence for Gondwanaland: the shared Glossopteris flora, Permo-Carboniferous tillites on every fragment, and land reptiles such as Lystrosaurus in India, Africa and Antarctica.','Land plants and reptiles cannot cross oceans, and ice sheets do not form at the equator. So the lands were once joined near the south pole.','TNPSC Geology (Degree Std, CUGE/19) 2019',true,3,1,814) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f065','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Karoo (South Africa) equivalents of the Gondwana: Dwyka tillite = Talchir, Ecca coal measures = Damuda, Beaufort beds with Lystrosaurus = Panchet.','Same ice, same coal, same reptile, in the same order. Hook: D-E-B in Africa matches T-D-P in India.',null,true,2,2,815) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f066','geological-assistant','geological-assistant-m2','Gondwana system and Gondwanaland','Gondwanaland began to break up in the Jurassic; India left Antarctica-Australia in the Early Cretaceous, Madagascar about 88-90 million years ago, and the Seychelles about 65 million years ago.','Each split has its lava: Rajmahal for the first, Deccan for the Seychelles split.',null,true,2,2,816) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f067','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','Tertiary of Assam, oldest to youngest: Jaintia (Eocene), Barail (Oligocene), Surma (Lower Miocene), Tipam (Miocene), Dupi Tila (Mio-Pliocene), Dihing (Plio-Pleistocene).','Hook: ''Just Bring Some Tea, Dear Deepa''. Beds change upward from marine to river deposits as the sea withdrew.',null,true,3,1,817) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f068','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The Jaintia Group (Eocene shelf beds of Meghalaya-Assam) has three parts: Therria Sandstone, Sylhet Limestone (nummulitic) and Kopili Shale; its deep-water equivalent is the Disang Shale.','Nummulites are coin-shaped foraminifera typical of the Eocene. Shelf limestone passes into basin mud toward the Naga Hills.',null,true,2,2,818) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f069','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The Tertiary coal of Upper Assam (Makum field) lies in the Oligocene Barail Group; unlike Gondwana coal it is low in ash but high in sulphur.','It formed in coastal swamps touched by sea water, which adds sulphur. Low ash, high sulphur is the Tertiary coal signature.','IIT-JAM Geology 2017',true,3,1,819) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f070','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','At Digboi (Assam) oil is produced from the Tipam Sandstone (Miocene); the Girujan Clay above it is the cap rock. At Naharkatiya, Barail (Oligocene) sands are the main producers.','Oil needs a porous sandstone to hold it and a tight clay to seal it. Tipam = tank, Girujan = lid.',null,true,3,1,820) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f071','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','Sub-Himalayan Tertiary of Himachal (Sirmur Group), oldest to youngest: Subathu (marine, nummulitic, Paleocene-Eocene), Dagshai (red continental beds), Kasauli (grey sandstone with plant fossils).','Subathu is the last sea deposit of the foothills. After it only rivers laid sediment, so the land had risen.','UPSC Geologist Exam 2018 (Geology Paper I)',true,3,1,821) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f072','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The Murree Group of the Jammu and Potwar foothills is a thick Oligocene-Lower Miocene pile of red and purple continental sandstone and clay, equivalent to the Dagshai and Kasauli; the Siwalik Group lies above it.','It is the first river debris shed from the young Himalaya. Order: Subathu (sea), Murree (river), Siwalik (river).',null,true,3,1,822) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f073','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','Classical Tertiary sequence of Sind, oldest to youngest: Ranikot (Paleocene), Laki and Kirthar (Eocene), Nari (Oligocene), Gaj (Lower Miocene), Manchhar (Mio-Pliocene, Siwalik equivalent).','The older units are marine, with nummulitic limestones. The Manchhar on top is river-laid, like the Siwaliks.',null,true,2,2,823) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f074','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The Tertiary of Kutch rests on weathered Deccan Trap and runs from Paleocene to Pliocene; its Eocene Fulra Limestone is packed with larger foraminifera such as Nummulites.','Kutch is the reference section for the marine Tertiary of western India. Biswas gave the modern formation names.',null,true,2,2,824) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f075','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The Cuddalore Sandstone (Mio-Pliocene) of Tamil Nadu holds the Neyveli lignite, India''s largest lignite deposit; the Palana lignite of Bikaner (Rajasthan) is of Paleocene-Eocene age.','Lignite is young, soft brown coal. At Neyveli, sands under the seam hold water under pressure and must be pumped during mining.','IIT-JAM Geology 2017',true,3,1,825) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f076','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','In Kerala, sedimentary rocks are limited to Tertiary and Quaternary beds of the coastal belt, resting unconformably on Precambrian crystalline rocks.','Kerala has no exposed Palaeozoic or Mesozoic sediments. The Ghats and midlands are charnockite, khondalite and gneiss.',null,true,3,1,826) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f077','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','Tertiary sequence of Kerala, oldest to youngest: Vaikom Formation, Quilon Formation, Warkalli Formation, usually capped by laterite.','Hook: V-Q-W, alphabetical going up. Older books list only the Quilon and Warkalli beds.','Kerala PSC Assistant Geologist 2025 (QP 26/2025/OL)',true,3,1,827) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f078','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The Vaikom Formation is gravel, coarse sandstone and clay with carbonaceous clay and thin lignite seams, lying below the Quilon beds.','It is a river-laid, non-marine unit. Named after Vaikom in Kottayam district.',null,true,2,2,828) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f079','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','Boreholes in the Alappuzha area show an older buried unit below the Vaikom, the Alleppey beds: carbonaceous clay with lignite, thought to be Eocene and nowhere exposed.','It is known only from drilling by groundwater agencies. So the full subsurface order is Alleppey, Vaikom, Quilon, Warkalli.',null,false,1,3,829) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f080','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The Quilon Formation is a marine, fossil-rich limestone with marl and clay of Lower Miocene age; its type area is Padappakkara near Kollam.','It is the only clearly marine Tertiary unit exposed in Kerala. Its corals, molluscs and foraminifera record a short sea advance.',null,true,3,1,830) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f081','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The Warkalli Formation (Mio-Pliocene) is sandstone and variegated clay with carbonaceous clay, lignite and marcasite; its type section is the Varkala cliff, Thiruvananthapuram district.','Marcasite is an iron sulphide formed in swampy, oxygen-poor mud. The cliff is a GSI national geological monument; W. King named the beds in 1882.','Kerala PSC Assistant Geologist 2025 (QP 26/2025/OL)',true,3,1,831) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f082','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The Warkalli Formation of Kerala is correlated with the Cuddalore Sandstone of Tamil Nadu and the Ratnagiri beds of Maharashtra.','All three are young coastal sands and clays with lignite, laid at about the same time on the two coasts.',null,true,2,2,832) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f083','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','Kerala''s Tertiary lignite occurs as thin seams in the Warkalli beds, as at Varkala and in the Madayi-Pazhayangadi area of Kannur and at Nileswaram; the same beds give china clay at Kundara and Madayi.','Coastal swamps left thin lignite, too thin for large mining. The white clays feed Kerala''s ceramic industry.',null,true,2,2,833) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f084','geological-assistant','geological-assistant-m2','Stratigraphy of the Cenozoic formations of India','The sands of the Warkalli and Vaikom formations are the main confined (pressure) aquifers of coastal Kerala; the Warkalli aquifer is the most widely developed, while the Quilon limestone-clay unit is a poor aquifer.','Sand and gravel store and pass water well. Clay and marl do not, so they act as confining layers. Alappuzha''s water supply taps these Tertiary sands.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,834) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f085','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','Himalayan belts from south to north: Sub-Himalaya (Siwalik), Lesser Himalaya, Higher (Great) Himalaya, Tethys Himalaya, Indus-Tsangpo Suture Zone, Trans-Himalaya.','Each belt is a slice of crust stacked on the one to its south. The suture is the join between India and Asia.','UPSC Geologist Exam 2018 (Geology Paper I)',true,3,1,835) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f086','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','Thrusts from south to north: HFT (plains against Siwalik), MBT (Siwalik against Lesser Himalaya), MCT (Lesser against Higher Himalaya); the South Tibetan Detachment, a normal fault, separates the Higher Himalaya from the Tethyan sediments.','HFT = Himalayan Frontal Thrust, MBT = Main Boundary Thrust, MCT = Main Central Thrust. Hook going north: F-B-C.',null,true,3,1,836) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f087','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','The Indus-Tsangpo Suture Zone marks where India joined Asia; it contains ophiolites (slices of Tethys ocean floor), melange and the Dras island-arc volcanics.','A suture is the scar left when an ocean closes. Ophiolite = ocean crust pushed up on land.',null,true,3,1,837) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f088','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','The Trans-Himalayan (Ladakh) batholith is a belt of Cretaceous-Eocene granitic rocks formed above the subducting Tethys ocean floor, before India and Asia collided.','It is an Andes-type magmatic arc on the Asian edge. It lies just north of the Indus suture.',null,true,2,2,838) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f089','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','India collided with Asia about 50-55 million years ago (Early Eocene), closing the Tethys sea.','The last marine beds (Eocene nummulitic limestone of Ladakh, Subathu of the foothills) show when the sea finally left.',null,true,3,1,839) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f090','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','Main phases of Himalayan uplift (Wadia): end of Eocene to Oligocene, Middle Miocene (the strongest), and end of Pliocene to Pleistocene, which folded the Siwaliks and tilted the Karewas.','Each push is dated by the youngest beds it folded. Krishnan adds an earlier Late Cretaceous phase and a latest sub-Recent one.',null,true,3,1,840) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f091','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','The Himalayan thrusts get younger southward: MCT (Early Miocene), MBT (Late Miocene), HFT (Quaternary and still active).','As India keeps pushing north, the mountain front steps out toward the plains. The newest break is at the foot of the hills.',null,true,3,1,841) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f092','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','The Himalayan arc ends in two sharp hairpin bends called syntaxes: the north-western at Nanga Parbat and the north-eastern at Namcha Barwa.','The mountain chains wrap around the two corners of the Indian plate. D.N. Wadia described the north-western syntaxis.',null,true,2,2,842) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f093','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','The Higher Himalaya is made of high-grade Central Crystallines intruded by Miocene tourmaline-bearing leucogranites, such as the Gangotri (Badrinath) and Manaslu granites.','Leucogranite is a pale granite formed by melting of thickened crust. Its Miocene age dates the peak of mountain building.',null,true,2,2,843) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f094','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','The Siwalik Group is a 5-6 km thick pile of freshwater river sediment (molasse) laid in the foreland basin in front of the rising Himalaya, from Middle Miocene to Lower Pleistocene.','A foreland basin is the trough made when the mountain load bends the crust down. Molasse = debris shed from a rising range.','IIT-JAM Geology 2017',true,3,1,844) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f095','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','Siwalik divisions: Lower (Kamlial, Chinji), Middle (Nagri, Dhok Pathan), Upper (Tatrot, Pinjor, Boulder Conglomerate).','Hook: ''Kamal Chose Nagpur, Dad Took Pinky By car''. All names are places in the Potwar-Punjab foothills.','TNPSC Geology (Degree Std, CUGE/19) 2019',true,3,1,845) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f096','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','Siwalik rocks coarsen upward: Lower = sandstone with red-purple mudstone; Middle = thick grey ''pepper-and-salt'' sandstone; Upper = sand, clay and boulder conglomerate.','Coarser debris on top means the mountains were rising and coming closer. Boulders at the top record the last big uplift.',null,true,3,1,846) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f097','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','Flysch is deep-marine mud and turbidite sand laid before and during mountain building; molasse is the later, mostly continental, coarse debris. The Siwaliks and Murrees are molasse; the Indus Flysch is flysch.','Flysch = sea, early. Molasse = land, late. Both are Alpine terms applied to the Himalaya.',null,true,3,1,847) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f098','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','Pascoe and Pilgrim (1919) explained the long, narrow Siwalik belt as the deposit of one great river, the ''Indobrahm'' or ''Siwalik River'', flowing north-west along the Himalayan foot.','Later workers prefer many south-flowing rivers building joined alluvial fans. The old single-river idea is still asked by name.',null,true,2,2,848) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f099','geological-assistant','geological-assistant-m2','Rise of the Himalaya and evolution of Siwalik basin','After the Siwaliks were folded and uplifted in the Pleistocene, the foreland basin shifted south to become the present Indo-Gangetic trough.','The foredeep (trough in front of a mountain) moves outward as the thrust front advances. The Ganga plain is today''s ''Siwalik basin''.',null,true,2,2,849) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f100','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','The Quaternary (Pleistocene + Holocene) begins 2.58 million years ago, at the base of the Gelasian Stage (ratified by IUGS in 2009); the Holocene begins 11,700 years ago.','The 2.58 mark is when northern ice sheets began to grow strongly. The Holocene is the warm time after the last ice age.',null,true,3,1,850) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f101','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','The Holocene has three ages (ratified 2018): Greenlandian, Northgrippian and Meghalayan. The Meghalayan began 4,200 years ago; its reference record is a stalagmite from Mawmluh Cave, Meghalaya.','It starts with a widespread drought recorded in the cave deposit. It is the only age named after an Indian state.',null,true,3,1,851) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f102','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','The Middle Pleistocene is now the Chibanian Age (ratified 2020), beginning about 774,000 years ago near the Brunhes-Matuyama magnetic reversal.','Named after Chiba in Japan. A magnetic reversal is a world-wide time marker, handy for dating Quaternary beds.',null,true,1,3,852) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f103','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','At the Last Glacial Maximum, about 20,000 years ago, global sea level stood roughly 120 m lower than today.','Water was locked in ice sheets. Rising Holocene seas later drowned river mouths and built today''s coastal plains.',null,true,2,2,853) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f104','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','The Karewas are Plio-Pleistocene lake and river deposits of the Kashmir valley forming flat-topped terraces: Lower Karewa (Hirpur Formation) and Upper Karewa (Nagum Formation).','Kashmir was once a big lake dammed by the rising Pir Panjal. Karewa soil is famous for saffron.',null,true,3,1,854) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f105','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','De Terra and Paterson (1939) recognised four Pleistocene glacial stages separated by three interglacial stages in Kashmir.','They read the story from moraines (ice-dumped debris) and river terraces. Interglacial = warm gap between ice advances.',null,true,2,2,855) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f106','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','Bhangar is the older alluvium of the Indo-Gangetic plain (Pleistocene, above flood level, with kankar nodules); Khadar is the newer flood-plain alluvium (Holocene).','Kankar = lime nodules that need a long time to grow, so they mark old alluvium. Khadar is renewed by every flood.',null,true,3,1,856) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f107','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','Bhabar is the porous gravel belt along the Siwalik foothills where streams sink underground; Terai is the marshy belt just south of it where the water comes out again.','Coarse gravel drops first at the hill foot and lets water soak in. Finer beds further out force it back to the surface.',null,true,3,1,857) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f108','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','Ash from the Toba super-eruption of Sumatra (Youngest Toba Tuff, about 74,000 years old) forms a marker bed in the Quaternary alluvium of the Son, Narmada and other Indian valleys.','One ash fall landed everywhere at the same moment. So it ties far-apart river sections to one date.',null,true,2,2,858) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f109','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','The Miliolite Limestone of coastal Saurashtra (Porbandar stone) is a Pleistocene calcareous sand rock rich in miliolid foraminifera.','Named after the tiny Miliolid shells. It is a popular soft building stone of Gujarat.',null,true,2,2,859) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f110','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','Teri sands are red, wind-blown Late Quaternary dune sands of the south Tamil Nadu coast (Tirunelveli-Thoothukudi), stained by iron oxide and carrying heavy minerals.','The red colour is a thin iron-oxide coat on the grains. They carry ilmenite and garnet.',null,true,2,2,860) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f111','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','The term laterite was coined by Francis Buchanan in 1807 for the rock at Angadipuram, Malappuram district, Kerala.','Latin ''later'' means brick: the soft rock is cut into blocks that harden in air. The site is a GSI national geological monument.',null,true,3,1,861) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f112','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','Laterite is a residual weathering product of hot climates with alternate wet and dry seasons, rich in iron and aluminium hydroxides; high-level laterite caps plateaus, low-level laterite covers coastal lowlands.','Rain washes out silica and bases; iron and aluminium stay behind. Residual means formed in place, not transported.',null,true,3,1,862) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f113','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','In Kerala laterite caps the Precambrian crystalline rocks of the midlands and also the Tertiary Warkalli beds of the coast.','So lateritisation went on after the Warkalli beds were laid, into the Quaternary. Laterite here is a key shallow aquifer for dug wells.',null,true,2,2,863) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f114','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','Quaternary coastal sediments of Kerala are beach and dune sands, old beach ridges, lagoon and backwater clays, peat and river alluvium; the Chavara beach sands hold ilmenite, rutile, zircon and monazite.','Rising Holocene seas and longshore drift built sand barriers. Lagoons (kayals) such as Vembanad were trapped behind them.',null,true,3,1,864) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2d-f115','geological-assistant','geological-assistant-m2','Quaternary stratigraphy','GSI divides the Quaternary of coastal Kerala by origin: Guruvayur Formation (old beach ridges), Viyyam Formation (tidal flats), Periyar Formation (river alluvium), Kadappuram Formation (present beaches).','Each name tells the setting: old beach, tidal mud, river, modern beach. Kadappuram simply means seashore in Malayalam.',null,false,1,3,865) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f001','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Crystals are grouped into seven crystal systems: cubic (isometric), tetragonal, hexagonal, trigonal, orthorhombic, monoclinic and triclinic. Older books count six by placing trigonal inside hexagonal.','Systems are defined by the lengths of the crystal axes and the angles between them. Symmetry falls from cubic (highest) to triclinic (lowest).',null,true,3,1,866) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f002','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','There are 32 crystal classes (point groups), 14 Bravais lattices and 230 space groups.','Hook: 7 systems - 14 lattices - 32 classes - 230 space groups. Classes describe the outer symmetry of a crystal; space groups describe the inner arrangement of atoms.',null,true,3,1,867) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f003','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','The symmetry elements of crystals are the plane (mirror), the axis of rotation and the centre. Rotation axes can only be 2-, 3-, 4- or 6-fold; a 5-fold axis is impossible.','Five-fold units cannot fill space without gaps, just as regular pentagon tiles cannot cover a floor. So a repeating crystal lattice cannot have a 5-fold axis.','Kerala PSC HSST Geology 2026 (QP 80/2026/OL)',true,3,1,868) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f004','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','The cubic system has three equal axes at right angles (a = b = c). Its diagnostic symmetry is four 3-fold axes, which run along the body diagonals of the cube.','Every cubic class keeps the four 3-fold axes, even classes such as pyrite''s that have no 4-fold axis. Examples: galena, garnet, halite, fluorite, magnetite.',null,true,3,1,869) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f005','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','The normal (galena-type) class of the cubic system has the highest symmetry of any crystal: 9 planes, 13 axes (three 4-fold, four 3-fold, six 2-fold) and a centre.','Hook: 9 + 13 + 1 = 23 symmetry elements. The 9 planes are 3 axial planes plus 6 diagonal planes.',null,true,3,1,870) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f006','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Tetragonal crystals have a = b but c different, with all angles 90°, and one 4-fold axis. Examples: zircon, rutile, cassiterite, chalcopyrite.','Think of a cube stretched or squashed along one axis. That special axis (c) is the single 4-fold axis.',null,true,2,2,871) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f007','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Hexagonal crystals use four axes: three equal horizontal axes at 120° and a vertical c axis. The hexagonal division has one 6-fold axis (beryl, apatite); the trigonal division has one 3-fold axis (quartz, calcite, tourmaline, corundum).','It is the only system described with four axes. Hook: beryl and apatite are ''six-siders''; quartz and calcite are ''three-siders''.',null,true,3,1,872) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f008','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Orthorhombic crystals have three unequal axes, all at 90°. Their symmetry is three 2-fold axes, or one 2-fold axis with two mirror planes. Examples: olivine, barite, topaz, sulphur, aragonite.','Think of a matchbox: three different edge lengths but all corners square. No axis is higher than 2-fold.','GATE Geology and Geophysics 2012',true,2,2,873) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f009','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Monoclinic crystals have three unequal axes with one oblique angle (beta is not 90°). The highest symmetry is one 2-fold axis, one plane and a centre. Examples: orthoclase, gypsum, augite, hornblende, micas.','Mono-clinic means ''one inclination'': only one axis leans. More common minerals belong to this system than to any other.',null,true,3,1,874) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f010','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Triclinic crystals have three unequal axes and no right angles between them. The highest possible symmetry is only a centre. Examples: plagioclase, microcline, kyanite, axinite.','Tri-clinic means ''three inclinations'': all three axes lean. It is the least symmetric system.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,875) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f011','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Miller indices of a crystal face are the reciprocals of its intercepts on the crystal axes, cleared of fractions. A face parallel to an axis gets the index 0 for that axis.','Example: intercepts 1a, 2b and parallel to c. Reciprocals are 1, 1/2, 0. Multiply by 2 to get (210). Parallel means the intercept is infinity, and 1/infinity = 0.',null,true,3,1,876) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f012','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Steno''s law of constancy of interfacial angles: in all crystals of the same mineral, the angles between corresponding faces are the same. These angles are measured with a goniometer.','Faces can grow large or small, but the atomic framework fixes the angles between them. A contact goniometer suits large crystals; a reflecting goniometer suits small bright ones.',null,true,3,1,877) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f013','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','A crystal form is a set of faces related by symmetry. Closed forms enclose space (cube, octahedron, dipyramid). Open forms do not: pedion (1 face), pinacoid (2 parallel faces), prism, pyramid.','An open form must combine with another form to make a whole crystal. A prism needs a basal pinacoid {001} or a pyramid to close its ends.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,2,2,878) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f014','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Common cubic forms: the cube {100} has 6 faces, the octahedron {111} has 8 faces and the rhombic dodecahedron {110} has 12 faces.','A cube face cuts one axis and is parallel to two. An octahedron face cuts all three equally. A dodecahedron face cuts two axes and is parallel to the third.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,3,1,879) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f015','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Three cubic forms have 24 faces: tetrahexahedron {hk0}, trapezohedron {hll} and trisoctahedron {hhl}. The hexoctahedron {hkl} has 48 faces, the largest number in any crystal form.','Trapezohedron is the usual shape of leucite and analcime crystals and is common in garnet. 48 is the ''general form'' of the highest-symmetry class.','Goa PSC Assistant Professor (Geology) 2021',true,2,2,880) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f016','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Mohs scale of hardness: talc 1, gypsum 2, calcite 3, fluorite 4, apatite 5, orthoclase 6, quartz 7, topaz 8, corundum 9, diamond 10.','Hook: ''The Girls Can Flirt And Other Queer Things Can Do''. The scale is only relative: diamond is many times harder than corundum, not just one step.',null,true,3,1,881) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f017','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Kyanite has two hardnesses: about 4.5-5 along the length of the blade and about 6.5-7 across it. Its old name, disthene, refers to this.','Disthene means ''two strengths''. A knife scratches a kyanite blade lengthwise but not crosswise. It is the classic example of hardness varying with direction.',null,true,3,1,882) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f018','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Cleavage directions: micas 1 (basal); pyroxenes, amphiboles and feldspars 2; halite and galena 3 at 90° (cubic); calcite 3 not at 90° (rhombohedral); fluorite 4 (octahedral); sphalerite 6 (dodecahedral).','Cleavage is smooth breaking along planes of weak atomic bonds. Hook: 1 mica - 2 chains and feldspars - 3 cubes and rhombs - 4 fluorite - 6 sphalerite.','Goa PSC Assistant Professor (Geology) 2021',true,3,1,883) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f019','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Quartz has no cleavage and breaks with a conchoidal (shell-like) fracture, while calcite has perfect rhombohedral cleavage. Cleavage is the best hand-specimen property to tell the two apart.','In quartz every direction has equally strong Si-O bonds, so there is no weak plane to split along. Hardness helps too: quartz 7, calcite 3.','Kerala PSC HSST Geology 2026 (QP 80/2026/OL); Goa PSC Assistant Geologist 2021',true,3,1,884) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f020','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Streak is the colour of a mineral''s fine powder, obtained by rubbing it on an unglazed porcelain plate. It is much more constant than body colour, which is the least reliable property.','Impurities change the colour of a lump but hardly change the colour of its powder. Hematite can be black, grey or red, yet its streak is always red.','Goa PSC Assistant Geologist 2021',true,3,1,885) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f021','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Diagnostic streaks: hematite cherry red to red-brown; magnetite black; chromite brown; limonite yellow-brown; pyrite and chalcopyrite greenish black; cinnabar scarlet; sphalerite pale yellow to brown.','Streak separates look-alike black ores quickly: magnetite black, chromite brown, hematite red. Gold gives a golden streak, but ''fool''s gold'' (pyrite) gives a dark one.',null,true,3,1,886) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f022','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Lustre types: metallic (galena, pyrite); adamantine (diamond); vitreous (quartz); resinous (sphalerite); pearly (talc, mica cleavage); silky (asbestos, satin spar); greasy (nepheline); earthy or dull (kaolin).','Lustre is how a surface reflects light. Silky lustre comes from parallel fibres; pearly lustre comes from light reflected off many thin cleavage sheets.',null,true,3,1,887) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f023','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Specific gravity is the weight of a mineral divided by the weight of an equal volume of water. Quartz 2.65, calcite 2.71, barite 4.5, pyrite 5.0, galena 7.5.','Most common rock-forming minerals fall between 2.6 and 3.4. Metallic ores are much heavier. Barite is called ''heavy spar'' because it is so heavy for a non-metallic mineral.',null,true,3,1,888) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f024','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Specific gravity is measured with Jolly''s spring balance, Walker''s steelyard balance or a pycnometer (density bottle). Bromoform (specific gravity 2.89) is the usual heavy liquid for separating heavy minerals.','All the balances weigh the mineral in air and then in water. In bromoform, quartz and feldspar float while ''heavy minerals'' such as zircon and garnet sink.','Uttarakhand PSC Geology (Series C) 2017',true,2,2,889) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f025','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Special properties: magnetite is strongly magnetic; halite tastes salty; talc feels soapy; clear calcite (Iceland spar) shows double refraction; quartz is piezoelectric; tourmaline is pyroelectric and piezoelectric.','Piezoelectric means the crystal develops electric charge when squeezed. It needs a crystal with no centre of symmetry. This is why quartz plates are used in watches and radios.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,2,2,890) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f026','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Olivine is a complete solid solution between forsterite (Mg2SiO4) and fayalite (Fe2SiO4): Mg2+ and Fe2+ replace each other freely in the same structure.','The two ions have the same charge and almost the same size, so the structure does not notice the swap. Such a series is also called an isomorphous series.','Kerala PSC HSST Geology 2026 (QP 80/2026/OL)',true,3,1,891) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f027','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Plagioclase is a complete solid solution from albite (NaAlSi3O8) to anorthite (CaAl2Si2O8) by coupled substitution: Na+ with Si4+ is replaced by Ca2+ with Al3+.','Na+ and Ca2+ are similar in size but differ in charge. Swapping one Si4+ for Al3+ at the same time keeps the total charge balanced.',null,true,3,1,892) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f028','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Polymorphs have the same chemical composition but different crystal structures: diamond-graphite (C), calcite-aragonite (CaCO3), pyrite-marcasite (FeS2), sphalerite-wurtzite (ZnS), and quartz-tridymite-cristobalite (SiO2).','Poly-morph means ''many forms''. Which form is stable depends on pressure and temperature. High pressure favours the denser form, such as diamond.',null,true,3,1,893) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f029','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Isomorphous minerals have the same crystal structure and similar formula type but different compositions, for example the calcite group: calcite CaCO3, magnesite MgCO3, siderite FeCO3, rhodochrosite MnCO3.','Iso-morph means ''same form''. It is the opposite idea to polymorphism: here the shape stays the same and the chemistry changes.','Kerala PSC HSST Geology 2026 (QP 80/2026/OL)',true,2,2,894) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f030','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Exsolution is the unmixing of a solid solution during slow cooling. Perthite is a potassium feldspar host with sodic feldspar (albite) lamellae; antiperthite is a plagioclase host with potassium feldspar lamellae.','At high temperature K and Na feldspar mix fully. On slow cooling they separate, like oil and water. On a phase diagram the curve below which unmixing starts is called the solvus.','Goa PSC Assistant Professor (Geology) 2021',true,3,1,895) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f031','geological-assistant','geological-assistant-m3','Structural classification of silicates','The building block of all silicates is the (SiO4)4- tetrahedron: one small Si4+ ion surrounded by four O2- ions at the corners, leaving a net charge of -4.','Charge: +4 from silicon and 4 x (-2) from oxygen gives -4. Tetrahedra balance this charge by bonding to metal ions or by sharing oxygens with each other.',null,true,3,1,896) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f032','geological-assistant','geological-assistant-m3','Structural classification of silicates','Silicates are classified by how many oxygens each tetrahedron shares: neso 0, soro 1, cyclo 2, single chain 2, double chain 2 and 3 alternately, phyllo 3, tecto 4.','More sharing means more linking (polymerisation) and less oxygen per silicon. So the Si:O ratio rises from 1:4 in olivine to 1:2 in quartz.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,897) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f033','geological-assistant','geological-assistant-m3','Structural classification of silicates','Nesosilicates (orthosilicates) have isolated (SiO4)4- tetrahedra with Si:O = 1:4. Examples: olivine, garnet, zircon, kyanite, sillimanite, andalusite, staurolite, topaz, sphene.','Neso means ''island''. The tetrahedra share no oxygens and are held together only by metal ions. The tight packing makes these minerals dense and hard.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,898) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f034','geological-assistant','geological-assistant-m3','Structural classification of silicates','Sorosilicates have pairs of tetrahedra sharing one oxygen, giving (Si2O7)6- groups with Si:O = 2:7. Examples: epidote, hemimorphite, melilite, lawsonite, vesuvianite.','Soro means ''group''; the pair looks like a bow-tie. Epidote and vesuvianite contain both paired groups and single tetrahedra.',null,true,3,1,899) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f035','geological-assistant','geological-assistant-m3','Structural classification of silicates','Cyclosilicates have rings of tetrahedra, each sharing two oxygens, with Si:O = 1:3; the common six-member ring is (Si6O18)12-. Examples: beryl, tourmaline, cordierite.','Cyclo means ''ring''. Rings stacked on one another make channels, which is why beryl and tourmaline grow as long prisms.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,900) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f036','geological-assistant','geological-assistant-m3','Structural classification of silicates','Single-chain inosilicates have tetrahedra sharing two oxygens in an endless chain, with Si:O = 1:3, written (SiO3)2- or (Si2O6)4-. The pyroxenes are the main examples.','Ino means ''thread''. The chains run parallel to the c axis and are bonded sideways by weaker metal-oxygen bonds. That gives two cleavages at nearly 90°.',null,true,3,1,901) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f037','geological-assistant','geological-assistant-m3','Structural classification of silicates','Double-chain inosilicates have two linked chains in which tetrahedra share two and three oxygens alternately, with Si:O = 4:11, written (Si4O11)6-. The amphiboles are the examples, and they contain (OH).','The wider double chain makes the cleavage angle 56° and 124° instead of about 90°. Hook: amphibole = 4:11 and hydrous; pyroxene = 1:3 and dry.',null,true,3,1,902) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f038','geological-assistant','geological-assistant-m3','Structural classification of silicates','Phyllosilicates have sheets in which each tetrahedron shares three oxygens, with Si:O = 2:5, written (Si2O5)2- or (Si4O10)4-. Examples: micas, chlorite, talc, serpentine, clay minerals.','Phyllo means ''leaf''. Bonds inside a sheet are strong but bonds between sheets are weak. This gives one perfect basal cleavage and soft, flaky minerals.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,903) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f039','geological-assistant','geological-assistant-m3','Structural classification of silicates','Tectosilicates have a three-dimensional framework in which all four oxygens of every tetrahedron are shared, with (Si,Al):O = 1:2. Examples: quartz, feldspars, feldspathoids, zeolites.','Tecto means ''framework''. In feldspars some Si4+ is replaced by Al3+; the missing charge is made up by K+, Na+ or Ca2+ sitting in the framework holes.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,904) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f040','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Olivine (Mg,Fe)2SiO4 is an orthorhombic nesosilicate: olive-green, glassy, hardness 6.5-7, with no good cleavage and conchoidal fracture. The gem variety is peridot.','It is the main mineral of dunite and peridotite and of the upper mantle. It alters easily to serpentine and is the first common silicate to weather.',null,true,3,1,905) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f041','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','Magnesium-rich olivine does not occur in equilibrium with free quartz: forsterite reacts with silica to form enstatite (Mg2SiO4 + SiO2 = 2MgSiO3).','Olivine is silica-poor (undersaturated), so any spare silica is used up to make pyroxene. The same rule bars nepheline and leucite from occurring with quartz.',null,true,3,1,906) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f042','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Garnets are cubic nesosilicates with the general formula X3Y2(SiO4)3. They form dodecahedral or trapezohedral crystals, have no cleavage, and have hardness 6.5-7.5.','X is a large 2+ ion (Mg, Fe, Mn, Ca); Y is a smaller 3+ ion (Al, Fe, Cr). Being hard with no cleavage, garnet is used as an abrasive.',null,true,3,1,907) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f043','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','Garnet species. Pyralspite series: pyrope Mg3Al2, almandine Fe3Al2, spessartine Mn3Al2. Ugrandite series: uvarovite Ca3Cr2, grossular Ca3Al2, andradite Ca3Fe2 (each with Si3O12).','The series names are built from the first letters. Almandine is the usual garnet of schists; pyrope occurs in kimberlite and eclogite; grossular and andradite occur in metamorphosed limestones (skarns).','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,3,1,908) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f044','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Pyroxenes are single-chain silicates with the general formula XYZ2O6. They show two cleavages at about 87° and 93° and a four- or eight-sided cross-section.','The narrow single chains stack like bricks, so the cleavages meet at almost a right angle. This is the quickest way to tell pyroxene from amphibole.','Kerala PSC HSST Geology 2026 (QP 80/2026/OL)',true,3,1,909) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f045','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Orthopyroxenes (enstatite MgSiO3, hypersthene, ferrosilite FeSiO3) are orthorhombic. Clinopyroxenes (diopside CaMgSi2O6, hedenbergite CaFeSi2O6, augite, pigeonite) are monoclinic.','Calcium-poor pyroxenes are mostly ortho; calcium-bearing ones are clino. Augite is the common pyroxene of basalt and gabbro. Hypersthene is the essential mineral of charnockite.',null,true,3,1,910) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f046','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','Sodic pyroxenes: jadeite NaAlSi2O6 (high-pressure rocks), aegirine NaFe3+Si2O6 (alkaline igneous rocks) and omphacite (eclogite). Spodumene LiAlSi2O6 is the lithium pyroxene of pegmatites.','Eclogite is made of green omphacite and red pyrope-rich garnet. Spodumene is an ore of lithium.','Uttarakhand PSC Geology (Series C) 2017',true,2,2,911) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f047','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Amphiboles are hydrous double-chain silicates. They show two cleavages at about 56° and 124° and a six-sided, diamond-shaped cross-section.','Hook: amphibole angles are ''far from 90'' (56/124); pyroxene angles are ''near 90'' (87/93). Amphiboles contain (OH), pyroxenes do not.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,912) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f048','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Amphibole species: anthophyllite (orthorhombic, Mg-Fe); tremolite Ca2Mg5Si8O22(OH)2 and actinolite (calcic); hornblende (calcic, aluminous, the commonest); glaucophane and riebeckite (sodic, blue).','Glaucophane is the blue amphibole of blueschists (high pressure, low temperature). Hornblende is the usual amphibole of diorite and amphibolite.','Uttarakhand PSC Geology (Series C) 2017',true,2,2,913) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f049','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Asbestos is of two kinds: chrysotile (fibrous serpentine, ''white asbestos'', the main commercial type) and amphibole asbestos such as crocidolite (blue asbestos, fibrous riebeckite) and amosite.','Serpentine Mg3Si2O5(OH)4 forms by alteration of olivine and pyroxene in ultramafic rocks. Its three forms are antigorite (platy), lizardite and chrysotile (fibrous).',null,true,2,2,914) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f050','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Micas are monoclinic sheet silicates with one perfect basal {001} cleavage. They split into thin flakes that are flexible and elastic; hardness is only 2-3.','Layers are held together by K+ ions, a weak link, so sheets peel off easily. Elastic means a bent flake springs back; chlorite flakes bend but stay bent.',null,true,3,1,915) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f051','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Mica species: muscovite KAl2(AlSi3O10)(OH)2 (white, potash mica); biotite K(Mg,Fe)3(AlSi3O10)(OH)2 (black); phlogopite (magnesium mica); lepidolite (lithium mica, lilac); glauconite (green, marine).','Muscovite is dioctahedral (two Al fill three sites); biotite and phlogopite are trioctahedral (three Mg or Fe fill three sites). Sericite is fine-grained muscovite.',null,true,3,1,916) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f052','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Talc Mg3Si4O10(OH)2 and pyrophyllite Al2Si4O10(OH)2 are sheet silicates with no ions between the layers, so they are very soft (hardness 1-2) and feel soapy.','The layers are neutral and held only by very weak (van der Waals) forces, so they slide over each other. Massive talc is called soapstone or steatite.',null,true,2,2,917) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f053','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Clay minerals: kaolinite has a 1:1 (T-O) layer and does not swell; illite is a 2:1 non-swelling clay with fixed K+; montmorillonite (smectite) is a 2:1 clay that swells and has high cation exchange capacity.','T = tetrahedral sheet, O = octahedral sheet. Water and ions enter between the weakly held layers of montmorillonite. Bentonite and black cotton soil are rich in it.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,3,1,918) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f054','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Kaolinite Al2Si2O5(OH)4 forms by weathering or hydrothermal alteration of feldspar (kaolinisation). Kerala''s china clay deposits at Kundara (Kollam) and Thonnakkal (Thiruvananthapuram) are well known.','Water and CO2 remove K, Na and Ca from feldspar and leave an aluminium silicate clay. China clay (kaolin) is used in ceramics and paper.',null,true,2,2,919) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f055','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Feldspars are framework silicates with three end members: orthoclase KAlSi3O8 (Or), albite NaAlSi3O8 (Ab) and anorthite CaAl2Si2O8 (An). Or-Ab is the alkali feldspar series; Ab-An is the plagioclase series.','K+ is too big and Ca2+ too different to mix, so there is almost no Or-An series. Feldspars are the most abundant minerals of the Earth''s crust.',null,true,3,1,920) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f056','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Plagioclase is divided by anorthite content: albite An0-10, oligoclase An10-30, andesine An30-50, labradorite An50-70, bytownite An70-90, anorthite An90-100.','Hook: ''All Old Aunts Love Baking Apples''. Basalt and gabbro carry labradorite; granite carries oligoclase. Fine parallel striations on cleavage faces identify plagioclase in hand specimen.',null,true,3,1,921) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f057','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','Potassium feldspar KAlSi3O8 has three polymorphs: sanidine (monoclinic, high temperature, in volcanic rocks), orthoclase (monoclinic, intermediate) and microcline (triclinic, low temperature, in granites and pegmatites).','Fast cooling in lavas freezes the disordered high-temperature form, sanidine. Slow cooling at depth lets Al and Si order into triclinic microcline. Amazonite is green microcline.','Goa PSC Assistant Professor (Geology) 2021',true,3,1,922) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f058','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Feldspars have hardness 6, specific gravity 2.55-2.76 and two good cleavages at or near 90°: exactly 90° in orthoclase and about 86° in plagioclase.','Ortho-clase means ''straight break''; plagio-clase means ''oblique break''. Hardness 6 and blocky cleavage separate feldspar from quartz, which has no cleavage.',null,true,2,2,923) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f059','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','Feldspathoids are silica-poor framework silicates that take the place of feldspar in silica-undersaturated rocks: nepheline (Na,K)AlSiO4, leucite KAlSi2O6, sodalite and kalsilite KAlSiO4. They never occur with quartz.','With free silica they would react to make feldspar (nepheline + silica = albite). Leucite forms trapezohedral crystals that look cubic but are tetragonal at room temperature.','Goa PSC Assistant Professor (Geology) 2021',true,3,1,924) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f060','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','At 1 atmosphere, low (alpha) quartz inverts to high (beta) quartz at 573 °C; tridymite is stable from 870 to 1470 °C, and cristobalite from 1470 °C to melting at 1713 °C.','Alpha quartz is trigonal; beta quartz is hexagonal. The 573 °C change only bends bonds (displacive), so it is fast and reversible. Quartz to tridymite breaks bonds (reconstructive) and is slow.',null,true,3,1,925) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f061','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','Coesite and stishovite are the high-pressure polymorphs of SiO2. Coesite marks ultra-high-pressure metamorphism and meteorite impact; stishovite, with silicon in six-fold coordination, is found at impact sites.','Pressure squeezes silica into denser structures. Quartz 2.65, coesite about 2.9, stishovite about 4.3. In stishovite each Si has six oxygen neighbours instead of four.','Kerala PSC HSST Geology 2026 (QP 80/2026/OL); UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019; Uttarakhand PSC Geology (Series C) 2017',true,3,1,926) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f062','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Chalcedony, agate, jasper, chert and flint are cryptocrystalline (very fine-grained) quartz. Opal is hydrous, non-crystalline silica (SiO2.nH2O) and is a mineraloid, not a true mineral.','A mineral must have an ordered atomic structure; opal has none. Coloured crystalline quartz varieties are amethyst (purple), citrine (yellow), rose quartz and smoky quartz.',null,true,2,2,927) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f063','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','Of the three Al2SiO5 polymorphs, kyanite is triclinic and the densest (specific gravity about 3.6); andalusite (orthorhombic, about 3.15) is the least dense; sillimanite is orthorhombic and fibrous.','Density explains the stability: dense kyanite is the high-pressure form and light andalusite the low-pressure form. Chiastolite is andalusite with a dark cross of carbon inclusions.',null,true,3,1,928) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f064','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Beryl Be3Al2Si6O18 is a hexagonal cyclosilicate that forms six-sided prisms with hardness 7.5-8; emerald (green) and aquamarine (blue-green) are its gem varieties.','Beryl occurs mainly in granite pegmatites and is the chief ore of beryllium. Do not confuse: ruby and sapphire are corundum, not beryl.',null,true,2,2,929) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f065','geological-assistant','geological-assistant-m3','Physical, chemical and crystallographic characteristics of common rock forming silicate mineral groups','Zeolites are hydrated aluminosilicate framework minerals with open channels, such as natrolite, stilbite, heulandite, chabazite and analcime. They show cation exchange and lose and regain water reversibly.','The name means ''boiling stone'' because they froth when heated. They fill gas cavities in Deccan basalts (Pune, Nashik) and are used as water softeners and molecular sieves.','Uttarakhand PSC Geology (Series C) 2017',true,3,1,930) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f066','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','Zircon ZrSiO4 is a tetragonal nesosilicate (hardness 7.5, specific gravity about 4.7) found as an accessory mineral in granites; it is the main mineral used for U-Pb dating.','Zircon takes uranium into its structure but rejects lead, and it survives weathering. So it also collects in beach sands such as those of Chavara, Kerala.',null,true,2,2,931) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f067','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','In an igneous rock, essential minerals decide the rock name (quartz and feldspar in granite); accessory minerals occur in small amounts (zircon, apatite, magnetite, sphene); secondary minerals form by later alteration (chlorite, sericite, serpentine, kaolinite).','Felsic (light) minerals are quartz, feldspars, feldspathoids and muscovite. Mafic (dark, Fe-Mg rich) minerals are olivine, pyroxene, amphibole and biotite.',null,true,2,2,932) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f068','geological-assistant','geological-assistant-m3','Common minerals of igneous and metamorphic rocks','Staurolite, kyanite, andalusite, sillimanite, cordierite, glaucophane and wollastonite are characteristic minerals of metamorphic rocks; leucite, nepheline and sanidine are essentially igneous minerals.','Metamorphic minerals grow in the solid state from aluminous or limy rocks under heat and pressure. Feldspathoids and sanidine need a hot silicate melt.',null,true,2,2,933) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f069','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Calcite CaCO3 is trigonal, with hardness 3, specific gravity 2.71 and perfect rhombohedral cleavage in three directions. It effervesces briskly in cold dilute HCl.','The acid releases CO2 gas, seen as fizzing. Clear calcite (Iceland spar) shows strong double refraction. Pointed ''dog-tooth spar'' crystals are scalenohedra.',null,true,3,1,934) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f070','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Aragonite is the orthorhombic polymorph of CaCO3. It is harder (3.5-4) and denser (2.95) than calcite, lacks rhombohedral cleavage, and slowly changes to calcite with time.','It is the denser, high-pressure form, so it is metastable (not truly stable) at the surface. Many shells and pearls are aragonite. It fizzes in cold acid like calcite.',null,true,3,1,935) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f071','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Dolomite CaMg(CO3)2 has hardness 3.5-4, specific gravity 2.85 and curved, saddle-shaped rhombohedral crystals. It effervesces in cold dilute HCl only when powdered, or in warm acid.','Powdering gives more surface for the weak reaction. In thin section, the stain Alizarin Red S turns calcite pink-red but leaves dolomite unstained.',null,true,3,1,936) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f072','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Carbonates of small cations (Mg, Fe, Mn, Zn) have the rhombohedral calcite structure; carbonates of large cations (Sr, Ba, Pb) have the orthorhombic aragonite structure. CaCO3 forms both.','Calcite group: magnesite, siderite, rhodochrosite, smithsonite ZnCO3. Aragonite group: strontianite SrCO3, witherite BaCO3, cerussite PbCO3. Calcium is the in-between size.','UPSC Assistant Hydrogeologist (CGWB) Recruitment Test 2019',true,2,2,937) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f073','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Siderite FeCO3 is a brown rhombohedral carbonate with specific gravity about 3.9. It becomes magnetic on heating and is an ore of iron (about 48% Fe), called spathic iron ore.','Hook: sideros is Greek for iron. It is the heaviest of the rock-forming carbonates (calcite, dolomite, magnesite, siderite) and reacts with acid only when the acid is hot.',null,true,2,2,938) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f074','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Magnesite MgCO3 usually occurs as white, compact, porcelain-like masses formed by alteration of ultramafic rocks. It is used for refractory bricks; the Chalk Hills of Salem, Tamil Nadu, are the classic Indian locality.','CO2-bearing water attacks Mg-rich serpentinite and deposits veins of magnesite. Refractory means it withstands very high furnace temperatures.',null,true,2,2,939) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f075','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Apatite Ca5(PO4)3(F,Cl,OH) is hexagonal with hardness 5. It is the commonest phosphate mineral, an accessory in most igneous rocks, and the main source of phosphorus for fertilisers.','Sedimentary rock phosphate (phosphorite) is made of very fine apatite called collophane, as at Jhamarkotra, Rajasthan. Bones and teeth are also a form of apatite.',null,true,3,1,940) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u3a-f076','geological-assistant','geological-assistant-m3','Minerals of the carbonate, phosphate, sulphide and halide groups','Monazite (Ce,La,Nd,Th)PO4 is a monoclinic, yellow-brown, resinous, heavy (specific gravity about 5) rare-earth phosphate. It is the chief ore of thorium and occurs in the beach sands of Chavara, Kerala.','It is radioactive because of thorium. Being heavy and resistant, it collects with ilmenite, rutile, zircon and sillimanite in the placers of Kerala and Manavalakurichi (Tamil Nadu).',null,true,3,1,941) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
